import React,{useEffect,useState,useCallback} from 'react';
import {BRAND_ASSETS} from './brand-assets';
import {ArrowClockwise,CheckCircle,Info,Sparkle} from '@phosphor-icons/react';
import {FormSection} from './form-section';

// Injected by vite.config.mjs at build time. The same values are published as /version.json so a running
// tab can tell when a newer build has been deployed.
export const APP_VERSION=typeof __APP_VERSION__==='string'?__APP_VERSION__:'0.0.0';
export const BUILD_ID=typeof __BUILD_ID__==='string'?__BUILD_ID__:'dev';
export const BUILD_TIME=typeof __BUILD_TIME__==='string'?__BUILD_TIME__:'';

// Newest first. Keep entries short; they are shown in Settings → About & updates.
export const RELEASE_NOTES=[
 {"version": "1.75.0", "date": "2026-11-13", "en": ["Calendar and Tasks: repeat on your own schedule. Choose Repeats → Custom for \"every 42 days\", \"every 6 weeks\" or \"every 3 months\", and see the next dates before you save. Bayit AI can set these up too.", "Saving is lighter on Bayit's server, so changes and the 5-second refresh are stopped less often on Cloudflare's free plan. A save can still sometimes take a second try; nothing is lost.", "When Bayit's server can't be reached, the bar says so plainly and what is waiting (\"Your layout choice is waiting to be saved\"). The change stays on this device and is retried until it goes through.", "Today's Expenses and Bills cards no longer say \"available after signing in\" when you are signed in and the server didn't answer. They say the server could not be reached, try once more by themselves and offer Try again."], "he": ["לוח שנה ומשימות: חזרה לפי מה שמתאים לכם. בוחרים חזרה ← מותאם אישית: \"כל 42 יום\", \"כל 6 שבועות\" או \"כל 3 חודשים\", ורואים את המועדים הבאים לפני השמירה. גם בַּיִת AI יודע ליצור חזרה כזאת.", "השמירה מכבידה פחות על השרת של Bayit, כך ששינויים והרענון כל 5 שניות נעצרים פחות בתוכנית החינמית של Cloudflare. לפעמים שמירה עדיין צריכה ניסיון נוסף; שום דבר לא הולך לאיבוד.", "כשאי אפשר להגיע לשרת של Bayit, הפס אומר זאת בפשטות ומה ממתין (\"בחירת התצוגה שלך ממתינה לשמירה\"). השינוי נשמר במכשיר הזה ונשלח שוב עד שהוא עובר.", "כרטיסי ההוצאות והחשבונות ב\"היום\" כבר לא כותבים \"זמין אחרי התחברות\" כשאתם מחוברים והשרת לא ענה. הם אומרים שלא הצלחנו להגיע לשרת, מנסים שוב פעם אחת בעצמם ומציעים לנסות שוב."]},
 {"version": "1.74.0", "date": "2026-11-12", "en": ["Shopping › Prices and spending now shows prices from every receipt you can see, from all your lists and finished shops. Before, it could say \"No receipts yet\" after a shop was finished.", "A receipt in Shopping history can be downloaded: the photo (adults only, the same people who can view it), or its lines as a CSV file.", "Products you buy without writing them on the list are learned from your receipts, so they can come up in suggestions. Bags, deposits, discounts and similar lines are not counted.", "In a finished shop, each row shows what the receipt says. When the list used a different word, a small line says \"Your list said: …\".", "A receipt saved before version 1.71 on a list shared with chosen people is now visible to everyone on that list, including the list's owner. It is never shared wider than the list."], "he": ["קניות › מחירים והוצאות מציג עכשיו מחירים מכל הקבלות שאתם רשאים לראות, מכל הרשימות ומקניות שהסתיימו. קודם הוא יכול היה לכתוב \"אין עדיין קבלות\" אחרי שקנייה הסתיימה.", "אפשר להוריד קבלה מהיסטוריית הקניות: את התמונה (רק מבוגרים, אותם אנשים שרשאים לראות אותה), או את השורות שלה כקובץ CSV.", "מוצרים שקונים בלי לכתוב ברשימה נלמדים מהקבלות, כך שהם יכולים להופיע בהצעות. שקיות, פיקדון, הנחות ושורות דומות לא נספרים.", "בקנייה שהסתיימה, כל שורה מציגה מה כתוב בקבלה. כשברשימה הופיעה מילה אחרת, שורה קטנה אומרת \"ברשימה היה כתוב: …\".", "קבלה שנשמרה לפני גרסה 1.71 ברשימה ששותפה עם אנשים מסוימים גלויה עכשיו לכל מי שברשימה, כולל בעלי הרשימה. היא אף פעם לא משותפת רחב יותר מהרשימה."]},
 {"version": "1.73.0", "date": "2026-11-12", "en": ["Today has a Cards | List switch, like Calendar, Tasks and Shopping.", "Cards on Today is more compact for everyone: smaller faces and icons, one-line event notes and shorter gaps, so more of your day fits on the screen.", "List shows each event, task and item on one line, and hides nothing: the same items and links as in Cards.", "The \"Ask Bayit AI\" card stays exactly as it was, in both views.", "If you already chose List under Settings › Lists, Today opens as a list after this update. Today's own switch changes it back.", "Children get the switch too, and their choice is their own."], "he": ["במסך \"היום\" יש עכשיו מתג כרטיסים | רשימה, כמו ביומן, במשימות ובקניות.", "תצוגת הכרטיסים ב\"היום\" קומפקטית יותר לכולם: פרצופים וסמלים קטנים יותר, הערה של אירוע בשורה אחת ופחות רווחים, כך שיותר מהיום נכנס למסך.", "ברשימה כל אירוע, משימה ופריט מופיעים בשורה אחת, ושום דבר לא מוסתר: אותם פריטים וקישורים כמו בכרטיסים.", "הכרטיס \"שואלים את בית AI\" נשאר בדיוק כמו שהיה, בשתי התצוגות.", "מי שכבר בחר \"רשימה\" בהגדרות › רשימות יראה את \"היום\" כרשימה אחרי העדכון. המתג של \"היום\" מחזיר לכרטיסים.", "גם ילדים מקבלים את המתג, והבחירה שלהם היא שלהם."]},
 {"version": "1.72.0", "date": "2026-11-12", "en": ["Shopping: ticking an item no longer tells the family that you are shopping. A shop starts when you press \"Start shopping\", or answer \"Yes, I am shopping\" when your first tick asks.", "Lists no longer finish by themselves. The last tick, or Finish, asks \"Finished shopping?\" with what was bought and what was not, and you choose whether to finish, with or without a receipt photo.", "The list says where it stands: \"Planning\" with the number of items, or \"Shopping now · 2 of 5\" with Finish always there.", "After a shop, one quiet \"Last shop\" line replaces the old banners. To undo a finish, open the shop in Shopping history (in the ⋯ menu) and press \"Undo finish\".", "Shopping history now shows the shops of all your lists in one place. \"Complete list\" and \"Reuse for a new trip\" are gone from the ⋯ menu, and each person's own private list stays hidden while it is empty.", "The planned shop's checkbox in Today and Tasks now opens the list, and the task is done when the shop is finished. A shop in History shows every receipt line with its price, and asks \"Correct?\" when it is not sure which item a line belongs to."], "he": ["קניות: סימון פריט כבר לא מודיע למשפחה שאתם בקנייה. קנייה מתחילה כשלוחצים \"מתחילים לקנות\", או עונים \"כן, אני בקנייה\" כשהסימון הראשון שואל.", "רשימות כבר לא מסתיימות מעצמן. הסימון האחרון, או \"לסיים\", שואל \"סיימת לקנות?\" ומראה מה נקנה ומה לא, ואתם בוחרים אם לסיים, עם צילום קבלה או בלי.", "הרשימה אומרת איפה היא עומדת: \"מכינים רשימה\" עם מספר הפריטים, או \"בקנייה עכשיו · 2 מתוך 5\" עם \"לסיים\" תמיד זמין.", "אחרי קנייה מופיעה שורה שקטה אחת, \"הקנייה האחרונה\", במקום ההודעות הקודמות. כדי לבטל סיום, פותחים את הקנייה בהיסטוריית הקניות (בתפריט ⋯) ולוחצים \"ביטול הסיום\".", "היסטוריית הקניות מציגה עכשיו את הקניות של כל הרשימות במקום אחד. \"סיום רשימה\" ו\"שימוש לקנייה חדשה\" הוסרו מתפריט ⋯, והרשימה הפרטית של כל אחד מוסתרת כל עוד היא ריקה.", "תיבת הסימון של הקנייה המתוכננת ב\"היום\" ובמשימות פותחת עכשיו את הרשימה, והמשימה מסתיימת כשהקנייה מסתיימת. קנייה בהיסטוריה מציגה כל שורה בקבלה עם המחיר שלה, ושואלת \"נכון?\" כשלא בטוח לאיזה פריט השורה שייכת."]},
 {"version": "1.71.0", "date": "2026-11-12", "en": ["Expenses has a new Categories tab: each category of the month with its total, the places you paid and every transaction. In Statistics, tapping a category opens it there.", "\"Who we pay\" keeps regular payees during the month, so it may list a few more providers mid-month and its monthly total may be a little higher.", "Shopping: when a shop is finished, what was bought moves to Shopping history and the list starts empty, with Undo. To finish with items left, press Finish on the green shopping line. A planned shop finished early counts for today.", "Receipt photos are now kept with the receipt in your installation's own file store. Only adults can see them, and deleting the receipt deletes the photo. Before this version the photo was not kept.", "Items someone adds to a shared list are now visible to the list's owner, including items added earlier. Renaming such an item saves again.", "Prices: one row per product, \"per kg\" only for weighed items, and cheapest/dearest once there are two purchases. A receipt paid partly by meal card or voucher now shows the full total."], "he": ["בהוצאות יש לשונית חדשה, קטגוריות: כל קטגוריה של החודש עם הסכום שלה, המקומות ששילמתם בהם וכל התנועות. בסטטיסטיקה, הקשה על קטגוריה פותחת אותה שם.", "\"למי משלמים\" שומר על תשלומים קבועים גם באמצע החודש, ולכן ייתכן שיופיעו בו עוד כמה ספקים באמצע החודש והסכום החודשי יהיה מעט גבוה יותר.", "קניות: כשקנייה מסתיימת, מה שנקנה עובר להיסטוריית הקניות והרשימה מתחילה ריקה, עם ביטול. כדי לסיים כשנשארו פריטים, לוחצים \"לסיים\" בשורת הקנייה הירוקה. קנייה מתוכננת שהסתיימה מוקדם נחשבת להיום.", "תמונות קבלה נשמרות עכשיו עם הקבלה, במאגר הקבצים של ההתקנה שלכם. רק מבוגרים רואים אותן, ומחיקת הקבלה מוחקת גם את התמונה. לפני הגרסה הזו התמונה לא נשמרה.", "פריטים שמישהו מוסיף לרשימה משותפת גלויים עכשיו גם לבעלי הרשימה, כולל פריטים שנוספו קודם. שינוי שם של פריט כזה נשמר שוב.", "מחירים: שורה אחת לכל מוצר, \"לק\"ג\" רק למוצרים שנשקלו, והזול והיקר מופיעים משתי קניות. קבלה ששולמה בחלקה בכרטיס סיבוס או בתו מציגה עכשיו את הסכום המלא."]},
 {"version": "1.70.0", "date": "2026-11-12", "en": ["Telegram: the morning message shows the shopping list only on a planned shop day, with its time and who is going. On other days, /shopping still shows any list.", "All bot messages have a new layout: a heading over a quote box, each line starting with the time and the name, with details in italics. Hebrew items in an English chat no longer jump between sides.", "What a child finishes during the day, and what waits for your OK, now arrives as one message that updates itself instead of a new message each time. The Approve buttons stay on it.", "A bot with no picture gets the Bayit logo. A picture you chose is kept; a parent can switch to the logo in Settings › Telegram › Manage the bot."], "he": ["טלגרם: הודעת הבוקר מציגה את רשימת הקניות רק ביום שבו מתוכננת קנייה, עם השעה ומי הולך. בימים אחרים, ‎/shopping עדיין מציג כל רשימה.", "לכל הודעות הבוט יש מבנה חדש: כותרת מעל תיבת ציטוט, כל שורה מתחילה בשעה ובשם, והפרטים בנטוי. פריטים בעברית בצ'אט באנגלית כבר לא קופצים מצד לצד.", "מה שילד מסיים במהלך היום, ומה שמחכה לאישור שלכם, מגיע עכשיו כהודעה אחת שמתעדכנת, במקום הודעה חדשה בכל פעם. כפתורי האישור נשארים עליה.", "בוט בלי תמונה מקבל את הלוגו של Bayit. תמונה שבחרתם נשמרת; הורה יכול להחליף ללוגו בהגדרות › טלגרם › ניהול הבוט."]},
 {"version": "1.69.0", "date": "2026-11-12", "en": ["Shopping: photograph a handwritten note. Your household's AI helper turns it into a list to tick; items already on the list start unticked, and nothing is added until you press \"Add N items\". The photo is not kept. For adults, from the list's ⋯ menu.", "Receipts: a line Bayit doesn't recognise asks \"Correct?\" once. Tell it what the line is and it remembers the name for the next receipt.", "Liked at home: an adult can keep a favourite to themselves with \"Only me\"; it is suggested only on their own private list.", "Parents can let a child's likes go straight in, child by child, in Shopping settings. By default every child still asks."], "he": ["קניות: אפשר לצלם פתק בכתב יד. עוזר ה־AI של הבית הופך אותו לרשימה לסימון; מה שכבר ברשימה מתחיל לא מסומן, ושום דבר לא נוסף עד שלוחצים \"הוספת N פריטים\". התמונה לא נשמרת. למבוגרים, מתפריט ⋯ של הרשימה.", "קבלות: שורה ש־Bayit לא מזהה שואלת \"נכון?\" פעם אחת. אומרים לו מה זה, והוא זוכר את השם לקבלה הבאה.", "אהובים בבית: מבוגר יכול לשמור אהוב לעצמו עם \"רק אני\"; הוא מוצע רק ברשימה הפרטית שלו.", "הורים יכולים לתת לבקשות של ילד להיכנס ישר, לכל ילד בנפרד, בהגדרות הקניות. כברירת מחדל כל ילד עדיין מבקש."]},
 {"version": "1.68.0", "date": "2026-11-12", "en": ["The shopping list now suggests what to buy. One card above the list, \"Before the shop\", based on what you usually buy. Go through the suggestions one at a time: add, already bought, not this time, or stop suggesting. It works without AI, and you can turn it off in Shopping settings.", "Liked at home: what each person likes is suggested when it hasn't been bought for a week. Children can ask, and a parent approves.", "The next shop's date shows on the list. When someone starts ticking, everyone sees they're shopping, and what is added meanwhile appears on top.", "Telegram: on shop day the morning summary says \"Shopping today\". Whoever is shopping gets each new item; each person can turn these messages off in Shopping settings. \"Add cucumbers and tomatoes\" adds at once, with Undo, even without AI.", "Photograph a receipt (adults, with an AI helper): your AI helper reads the prices, you check and save, and the photo is not kept. Then see prices over time and this month's supermarket spending from your statements."], "he": ["רשימת הקניות מציעה מה לקנות. מעל הרשימה יש כרטיס אחד, \"לפני הקנייה\", לפי מה שאתם קונים בדרך כלל. עוברים על ההצעות אחת אחת: להוסיף, כבר קנינו, לא הפעם, או להפסיק להציע. זה עובד בלי AI, ואפשר לכבות בהגדרות הקניות.", "אהובים בבית: מה שכל אחד אוהב מוצע כשלא נקנה שבוע. ילדים יכולים לבקש, והורה מאשר.", "התאריך של הקנייה הבאה מופיע על הרשימה. כשמישהו מתחיל לסמן, כולם רואים שהוא בקניות, ומה שמוסיפים בזמן הזה מופיע למעלה.", "בטלגרם: בבוקר של יום הקנייה כתוב \"היום יש קניות\". מי שבקניות מקבל כל פריט שנוסף, וכל אחד יכול לכבות את ההודעות האלה בהגדרות הקניות. \"תוסיף מלפפונים ועגבניות\" מוסיף מיד, עם כפתור ביטול, גם בלי AI.", "צילום קבלה, למבוגרים ועם עוזר AI: עוזר ה־AI שלכם קורא את המחירים, בודקים ושומרים, והתמונה לא נשמרת. אחר כך רואים מחירים לאורך זמן, וכמה הוצאתם בסופר החודש לפי הדוחות."]},
 {"version":  "1.67.0", "date":  "2026-11-11", "en":  ["Shopping: swipe an item left to delete it, like notifications, and delete a whole list from its ⋯ menu or edit window. Everyone who shares a list can remove its items, and Undo always brings them back."], "he":  ["קניות: מחליקים פריט שמאלה כדי למחוק אותו, כמו בהתראות, ואפשר למחוק רשימה שלמה מתפריט ⋯ או מחלון העריכה שלה. כל מי שהרשימה משותפת איתו יכול להסיר ממנה פריטים, ו\"ביטול\" תמיד מחזיר אותם."]},
 {"version":  "1.66.0", "date":  "2026-11-11", "en":  ["Bayit AI (in the app and on Telegram) now knows whose turn it is today and tomorrow, for the shower and other activities that take turns, including when a parent swapped the order. Turns that rotate daily now really change from one day to the next."], "he":  ["בית AI (באפליקציה ובטלגרם) יודע עכשיו של מי התור היום ומחר, במקלחת ובכל פעילות עם תורות, כולל כשהורה החליף את הסדר. תורות שמתחלפים מדי יום מתחלפים עכשיו באמת מיום ליום."]},
 {"version":  "1.65.1", "date":  "2026-11-11", "en":  ["Kids › Turns now lists only activities that take turns. Activities set to Together, like meals or getting dressed, no longer show a turn order, and the child's history still includes them."], "he":  ["ילדים › תורות מציג עכשיו רק פעילויות עם תורות. פעילויות שהוגדרו ״ביחד״, כמו ארוחות או התלבשות, כבר לא מוצגות עם סדר תורות, וההיסטוריה של הילד עדיין כוללת אותן."]},
 {"version":  "1.65.0", "date":  "2026-11-11", "en":  ["Tasks, Today and Calendar now open on what's yours: tasks and events assigned to you, plus whole-family ones, unassigned ones and birthdays. One tap on \"Show everyone\" shows the whole family, and Bayit remembers that choice on this device."], "he":  ["„משימות\", „היום\" ו„לוח שנה\" נפתחים עכשיו על מה שלכם: משימות ואירועים שמשויכים אליכם, וגם של כל המשפחה, כאלה בלי שיוך וימי הולדת. נגיעה אחת ב„הצגת כולם\" מציגה את כל המשפחה, ו־Bayit זוכר את הבחירה במכשיר הזה."]},
 {"version": "1.64.1", "date": "2026-11-11", "en": ["Bayit AI: a stray \"0\" no longer shows above your own typed message. Spoken questions still show their recording length.", "Running Bayit yourself with Docker: the quick start works again. A typo in compose.yaml stopped `docker compose up` on every machine; it is fixed, and an automatic check now runs the exact quick start. The Docker and Cloudflare guides now start with passkeys (no Google Cloud project needed), show where to find the one-time setup code, and include a restore command next to the backup."], "he": ["בית AI: ה־\"0\" המיותר כבר לא מופיע מעל ההודעה שהקלדתם. שאלות בקול עדיין מציגות את אורך ההקלטה.", "‏להריץ את Bayit בעצמכם עם Docker: ההתחלה המהירה עובדת שוב. טעות הקלדה ב־compose.yaml עצרה את `docker compose up` בכל מחשב. היא תוקנה, ועכשיו בדיקה אוטומטית מריצה בדיוק את ההתחלה המהירה. המדריכים ל־Docker ול־Cloudflare מתחילים עכשיו במפתחות גישה (בלי פרויקט ב־Google Cloud), מראים איפה נמצא קוד ההקמה החד־פעמי, וכוללים פקודת שחזור ליד פקודת הגיבוי."]},
 {"version": "1.64.0", "date": "2026-11-11", "en": ["A new installation now guides you from the first open: Bayit checks the address, the database and your browser before the setup code, then your name, passkey and family name, and ends with a short To start list: invite your family (a link per person, Send or Copy), and optionally the AI helper and Telegram. A card on Today keeps the rest until it's done. Families already using Bayit see no change.", "On small screens, the \"Own this installation and can't sign in?\" link no longer sits on the drawing."], "he": ["התקנה חדשה מלווה אתכם מהפתיחה הראשונה: Bayit בודק את הכתובת, את מסד הנתונים ואת הדפדפן לפני קוד ההקמה, ואחר כך השם, מפתח הגישה ושם המשפחה, ובסוף רשימת 'להתחלה' קצרה: להזמין את המשפחה (קישור לכל אחד, שליחה או העתקה), ואם רוצים גם עוזר AI וטלגרם. כרטיס ב'היום' שומר את מה שנשאר עד שמסיימים. משפחות שכבר משתמשות ב-Bayit לא יראו שינוי.", "במסכים קטנים הקישור 'בעלי ההתקנה ולא מצליחים להיכנס?' כבר לא יושב על הציור."]},
 {"version":  "1.63.0", "date":  "2026-11-11", "en":  ["One Bayit AI: the menu item and the floating button now open the same thing, with four tabs — Chat, Suggestions, History and Settings. Every AI option (connection, what Bayit AI may read, recommendations, daily ideas, the summary, the button, voice, usage and cost) now lives in one place, Bayit AI › Settings; Settings only links there."], "he":  ["בית AI אחד: פריט התפריט והכפתור הצף פותחים עכשיו את אותו הדבר, עם ארבע לשוניות — צ׳אט, הצעות, היסטוריה והגדרות. כל אפשרויות ה־AI (חיבור, מה בית AI רשאי לקרוא, המלצות, רעיונות יומיים, הסיכום, הכפתור, קול, שימוש ועלות) נמצאות עכשיו במקום אחד, בית AI ← הגדרות; ההגדרות הכלליות רק מקשרות לשם."]},
 {"version":  "1.62.0", "date":  "2026-11-11", "en":  ["Times sit neatly in the middle of their boxes everywhere, on iPhone too: quiet hours, events, reminders, Bayit AI and every other time field now share one control, the same height as the fields around it.", "Settings › Family: the account buttons are shorter (Disconnect, Help back in) and sit under the name on phones, so names are never covered. The daily suggestions settings are one tidy card with even spacing."], "he":  ["השעות יושבות עכשיו בדיוק באמצע התיבה בכל מקום, גם באייפון: שעות שקט, אירועים, תזכורות, בית AI וכל שדה שעה אחר משתמשים עכשיו באותו רכיב, באותו גובה כמו השדות שלידו.", "הגדרות › משפחה: כפתורי החשבון קצרים יותר (נתק, עזרה לחזור) ובטלפון הם מתחת לשם, כך שהשם תמיד גלוי. הגדרות ההצעות היומיות הן כרטיס אחד מסודר עם מרווחים אחידים."]},
 {"version":  "1.61.0", "date":  "2026-11-11", "en":  ["The kids' routines no longer fill grown-ups' Tasks and Today. They stay on the Kids screen; in Tasks, the \"Kids' routines\" filter shows them when you want, and Today shows one short line (\"Kids' routines · 7 of 12 done\") that opens Kids. One-off tasks for a child still show as usual."], "he":  ["שגרות הילדים כבר לא ממלאות את המשימות ואת מסך היום של המבוגרים. הן נשארות במסך הילדים; במשימות, המסנן \"שגרות הילדים\" מציג אותן כשרוצים, ובמסך היום מופיעה שורה קצרה אחת (\"שגרות הילדים · 7 מתוך 12 בוצעו\") שפותחת את מסך הילדים. משימות חד־פעמיות לילד ממשיכות להופיע כרגיל."]},
 {"version":  "1.60.0", "date":  "2026-11-10", "en":  ["Hundreds of new Bayit icons: about 340 new drawings in Bayit's style for events, Jewish, Israeli, Christian and Muslim holidays, birthdays and parties, health, school, clubs, travel, home, car, work, pets, weather and money. The icon window shows Recent first and a section per category, and search works in Hebrew and English (חנוכה, Hanukkah, פסח, party…). A new event starts with the Event icon."], "he":  ["מאות אייקונים חדשים: כ־340 איורים חדשים בסגנון של בית לאירועים, לחגים יהודיים, ישראליים, נוצריים ומוסלמיים, לימי הולדת ומסיבות, לבריאות, בית ספר, חוגים, טיולים, בית, רכב, עבודה, חיות, מזג אוויר וכסף. בחלון האייקונים מופיעים קודם האחרונים ואחר כך קטגוריה אחרי קטגוריה, והחיפוש עובד בעברית ובאנגלית (חנוכה, Hanukkah, פסח, מסיבה…). אירוע חדש מתחיל עם אייקון ״אירוע״."]},
 {"version": "1.59.0", "date": "2026-11-10", "en": ["Nothing visible changes for families in this version: you sign in with Google as before.", "Sign-in with a passkey (Face ID, fingerprint or your phone's screen lock instead of Google) is now part of Bayit, but it is switched off here until it has been tested on real phones."], "he": ["בגרסה הזו שום דבר לא משתנה למשפחות: נכנסים עם Google כמו קודם.", "כניסה עם מפתח גישה (Face ID, טביעת אצבע או נעילת המסך של הטלפון במקום Google) היא עכשיו חלק מ-Bayit, אבל היא כבויה כאן עד שתיבדק בטלפונים אמיתיים."]},
 {"version":  "1.58.2", "date":  "2026-11-10", "en":  ["Puzzle: every picture is now a full scene (the garden island and the moonlight garden no longer float on an empty background), and \"Choose another picture\" opens a window right on screen where you pick a picture and start a new puzzle."], "he":  ["פאזל: כל תמונה היא עכשיו סצנה מלאה (האי בגן והגן בלילה כבר לא מרחפים על רקע ריק), ו\"בחירת תמונה אחרת\" פותחת חלון ממש על המסך שבו בוחרים תמונה ומתחילים פאזל חדש."]},
 {"version":  "1.58.1", "date":  "2026-11-10", "en":  ["The Bayit AI button now steps aside while you fill in a form or use a window, so it never covers Save."], "he":  ["כפתור בית AI זז הצידה כשממלאים טופס או כשחלון פתוח, כך שהוא לא מסתיר את כפתור השמירה."]},
 {"version": "1.58.0", "date": "2026-11-10", "en": ["Nothing changes in how your family uses Bayit: same screens, and Telegram sends the same messages as before.", "For people who extend Bayit: Telegram now works through a general channel connection, so other messaging apps can be added the same way; a whole new screen with its own records can be added as an extension; updating Bayit keeps the extensions you installed; and there is a guided way to build a new extension, with new guides."], "he": ["שום דבר לא משתנה באופן שבו המשפחה משתמשת ב-Bayit: אותם מסכים, וטלגרם שולח את אותן הודעות כמו קודם.", "למי שמרחיב את Bayit: טלגרם עובד עכשיו דרך חיבור ערוצים כללי, כך שאפשר להוסיף באותה דרך אפליקציות הודעות אחרות; אפשר להוסיף כהרחבה מסך חדש שלם עם רשומות משלו; עדכון של Bayit שומר על ההרחבות שהתקנתם; ויש דרך מודרכת לבנות הרחבה חדשה, עם מדריכים חדשים."]},
 {"version":  "1.57.1", "date":  "2026-11-10", "en":  ["Drop-down lists and date pickers now always open on top: the icon category list in the icon picker (for example when adding an event) opened behind it and couldn't be seen."], "he":  ["רשימות נפתחות ובוחרי תאריך נפתחים עכשיו תמיד מעל הכול: רשימת הקטגוריות בבוחר האייקונים (למשל כשמוסיפים אירוע) נפתחה מאחוריו ולא נראתה."]},
 {"version":  "1.57.0", "date":  "2026-11-10", "en":  ["Statistics: Money is now called Expenses and comes right after Overview.", "Section menus show clearly when there is more: on most phones all of Statistics fits, and where it doesn't, part of the next tile shows and a short nudge points to it once. Swiping the menu moves at once."], "he":  ["סטטיסטיקה: \"כסף\" נקרא עכשיו \"הוצאות\" ומופיע מיד אחרי \"סקירה\".", "תפריטי האזורים מראים בבירור כשיש עוד: ברוב הטלפונים כל הסטטיסטיקה נכנסת, ובמקום שלא — חלק מהאריח הבא מציץ ותזוזה קצרה מראה אותו פעם אחת. החלקת התפריט זזה מיד."]},
 {"version":"1.56.0","date":"2026-11-10","en":["Settings › Accounts & connections is simpler: \"To start\" shows what to set up first, everything else waits under \"More connections\", and every connection opens the same step-by-step guide in one window.","The Telegram window is tidier: a parent sees a short summary and the family's chats, everyone else sees only \"My Telegram chat\", and Photos & voice has its own row.","How much AI Bayit uses now sits inside the AI window, and the Bayit AI recommendations switch moved to AI › Daily suggestions.","After you confirm with Google, changes to accounts and connections stay open for 30 minutes instead of 10, so a first setup no longer asks again halfway."],"he":["הגדרות ← חשבונות וחיבורים פשוט יותר: „להתחלה” מראה מה להגדיר קודם, כל השאר מחכה תחת „עוד חיבורים”, וכל חיבור נפתח עם אותו מדריך צעד אחר צעד בחלון אחד.","חלון טלגרם מסודר יותר: הורה רואה סיכום קצר ואת הצ׳אטים של המשפחה, כל השאר רואים רק „הצ׳אט שלי בטלגרם”, ול„תמונות והודעות קוליות” יש שורה משלהן.","כמה AI ‏Bayit משתמש מופיע עכשיו בתוך חלון ה־AI, והמתג של המלצות בית AI עבר ל־AI ← הצעות יומיות.","אחרי אישור עם Google, אפשר לשנות חשבונות וחיבורים במשך 30 דקות במקום 10, כך שהגדרה ראשונה כבר לא מבקשת אישור שוב באמצע."]},
 {"version":  "1.55.0", "date":  "2026-11-10", "en":  ["The Bayit AI button now sits exactly as far from the menu as from the side on every phone, and short notices no longer cover the menu or the button.", "The Ask Bayit AI page uses the same chat as the button: questions you tap are sent, you see Sent and Thinking, recordings show \"Turning your voice into text\", mixed Hebrew and English lines read in their own direction, and Prepare a plan is right in the chat."], "he":  ["כפתור בית AI יושב עכשיו באותו מרחק מהתפריט ומהצד בכל טלפון, והודעות קצרות כבר לא מכסות את התפריט או את הכפתור.", "מסך „שאלו את בית AI” משתמש באותו צ׳אט כמו הכפתור: שאלות שמקישים עליהן נשלחות, רואים „נשלח” ו„חושב”, בהקלטה מופיע „הופך את ההקלטה לטקסט”, שורות בעברית ובאנגלית נקראות כל אחת בכיוון שלה, ו„להכין תוכנית” נמצא בתוך הצ׳אט."]},
 {"version":  "1.54.0", "date":  "2026-11-10", "en":  ["Statistics › Money: a RiseUp card is no longer shown under the person who connected RiseUp. Cards nobody has claimed wait under \"Not assigned yet\" with \"Choose whose\". Bayit suggests whose a card is and its last 4 digits when the same purchases appear on an imported statement, or from the card's RiseUp nickname. You confirm, and it never makes up digits.", "The selected card is now clear: a gold ring on the front card and its whole row highlighted, with nothing jumping. Swipe the stack, use the arrows or dots, or tap \"+2\" to reach every card.", "Cards without an ending say where they're used most (e.g. \"mostly at Shufersal\"), so similar cards can be told apart."], "he":  ["סטטיסטיקה ← כסף: כרטיס מ־RiseUp כבר לא מופיע אצל מי שחיבר את RiseUp. כרטיסים שלא ידוע של מי הם מחכים תחת \"עדיין לא שויך\", עם כפתור \"לבחור של מי\". Bayit מציע של מי הכרטיס ומה 4 הספרות האחרונות שלו כשאותן קניות מופיעות בדף חשבון שהועלה, או לפי הכינוי של הכרטיס ב־RiseUp. אתם מאשרים, ו־Bayit אף פעם לא ממציא ספרות.", "עכשיו ברור איזה כרטיס נבחר: מסגרת זהב על הכרטיס שבחזית והשורה שלו מודגשת לכל הרוחב, בלי קפיצות. אפשר להחליק את הערימה, להשתמש בחיצים או בנקודות, או ללחוץ על \"+2\" כדי להגיע לכל כרטיס.", "כרטיס בלי סיומת מציין איפה הוא בשימוש הכי הרבה (למשל \"בעיקר בשופרסל\"), כך שאפשר להבדיל בין כרטיסים דומים."]},
 {"version":  "1.53.0", "date":  "2026-11-10", "en":  ["Who we pay: a company you pay for several things (like Cellcom for phone, internet and electricity) now reads clearly as one company with its services, and each company and each heading opens and closes."], "he":  ["למי משלמים: חברה שמשלמים לה על כמה דברים (כמו סלקום על טלפון, אינטרנט וחשמל) מוצגת עכשיו בבירור כחברה אחת עם השירותים שלה, ואפשר לפתוח ולסגור כל חברה וכל כותרת."]},
 {"version":  "1.52.0", "date":  "2026-11-10", "en":  ["Bayit AI on every screen: a floating Bayit AI button (or a side tab, or next to the bell — your choice in Settings › General) opens a chat over the screen you're on. Ask by typing or by voice, see clear Sent / Thinking / Answer steps, tap a task in the answer to open it, approve proposed changes, and find every past conversation in History (only you see yours)."], "he":  ["בית AI בכל מסך: כפתור בית AI צף (או לשונית בצד, או ליד הפעמון — לבחירתכם בהגדרות ← כללי) פותח צ׳אט מעל המסך שבו אתם נמצאים. שואלים בכתב או בהקלטה, רואים שלבים ברורים (נשלח / חושב / תשובה), מקישים על משימה בתשובה כדי לפתוח אותה, מאשרים שינויים מוצעים, וכל השיחות הקודמות נשמרות בהיסטוריה (רק אתם רואים את שלכם)."]},
 {"version":  "1.51.1", "date":  "2026-11-10", "en":  ["AI answers are now easy to scan: each part has its own icon and colour, times sit in small pills, and the people involved show with their faces."], "he":  ["התשובות של ה־AI נקראות עכשיו במבט: לכל חלק סמל וצבע משלו, השעות מופיעות בתגיות קטנות, והאנשים שקשורים מופיעים עם התמונה שלהם."]},
 {"version":  "1.51.0", "date":  "2026-11-10", "en":  ["A calmer header: the Bayit logo sits next to the menu, your family next to the notifications bell, and the saving sign no longer appears there.", "Answers from Bayit's AI in the app are easier to read: a short answer first, then clear sections and lists."], "he":  ["כותרת רגועה יותר: הלוגו של Bayit ליד התפריט, המשפחה ליד פעמון ההתראות, וסימן השמירה כבר לא מופיע שם.", "התשובות של ה־AI באפליקציה קלות יותר לקריאה: תשובה קצרה קודם, ואחריה חלקים ורשימות ברורים."]},
 {"version":  "1.50.1", "date":  "2026-11-10", "en":  ["Bayit AI has its final mark: a spark hugging the corner of the roof."], "he":  ["לבית AI יש את הסימן הסופי שלו: ניצוץ שצמוד לפינת הגג."]},
 {"version":  "1.50.0", "date":  "2026-11-10", "en":  ["Bayit AI: when it's on (Settings → Accounts & connections, a parent turns it on), Bayit looks at your money and adds things worth a check to Today and Tasks with its own mark — a new recurring charge (a forgotten trial), a price jump on a fixed charge, or the same charge twice. Tick to mark it checked, or open it to see the last months, why, and answer OK / Needs action (makes a task) / Not relevant. Electricity, water, gas and arnona aren't flagged for price changes. Adults only; choose a daily or weekly summary in Settings → Notifications."], "he":  ["בית AI: כשהוא מופעל (הגדרות ← חשבונות וחיבורים, הורה מפעיל), Bayit בודק את הכסף ומוסיף ל„היום שלנו” ולמשימות דברים שכדאי לבדוק, עם סימן משלו — חיוב קבוע חדש (ניסיון שנשכח), קפיצה במחיר של חיוב קבוע או אותו חיוב פעמיים. מסמנים ✓ כשבדקתם, או פותחים כדי לראות את החודשים האחרונים, למה, ולענות: תקין / צריך לטפל (נוצרת משימה) / לא רלוונטי. חשמל, מים, גז וארנונה לא מסומנים על שינויי מחיר. למבוגרים בלבד; סיכום יומי או שבועי בהגדרות ← התראות."]},
 {"version":  "1.49.0", "date":  "2026-11-10", "en":  ["You can now see Who we pay by company as well as by area: Cellcom's phone, internet and electricity in one card with the company total.", "Who we pay: electricity bought from a phone company (Cellcom Energy and others) is now electricity, separate from the phone bill; shop purchases and purchases paid in instalments no longer show as providers. Each provider shows its payment history and opens its payments in Transactions. The month control now works on this view, the categories are in a clearer order, and changing a provider's category works on phones (drop-down lists inside windows on phones can be tapped again)."], "he":  ["אפשר לראות עכשיו את \"למי משלמים\" גם לפי חברה ולא רק לפי תחום: הסלולר, האינטרנט והחשמל של סלקום בכרטיס אחד, עם הסך לחברה.", "למי משלמים: חשמל שנקנה מחברת סלולר (סלקום אנרג'י ואחרות) מוצג עכשיו כחשמל, בנפרד מחשבון הטלפון; קניות בחנויות ועסקאות בתשלומים כבר לא מופיעות כספקים. לכל ספק יש היסטוריית תשלומים ואפשר לפתוח את התשלומים שלו בתנועות. בחירת החודש עובדת עכשיו גם בתצוגה הזו, הקטגוריות מסודרות בסדר ברור יותר, ושינוי קטגוריה של ספק עובד בטלפון (אפשר שוב לבחור מרשימות נפתחות בתוך חלונות בטלפון)."]},
 {"version":  "1.48.1", "date":  "2026-11-10", "en":  ["Expenses on phones: the month no longer runs into the picker arrow.", "Statistics in Hebrew: the amounts on the side of the charts no longer run into the bars."], "he":  ["הוצאות בטלפון: החודש כבר לא נוגע בחץ הבחירה.", "סטטיסטיקה בעברית: הסכומים בצד הגרפים כבר לא נכנסים לתוך העמודות."]},
 {"version":  "1.48.0", "date":  "2026-11-09", "en":  ["Today: a new assistant at the top of Today. Ask your home a question, or turn a message into one plan with several items and a reminder for each, saved together so you can come back to it.", "Expenses: filter by whose card it is. Each adult appears with their cards stacked beside them, and bank accounts sit under Shared. Pick several at once, then narrow to single cards. Works the same for RiseUp and imported statements; before, \"Max\" missed every purchase synced through RiseUp.", "Statistics › Money: \"By person and card\" stacks each person's cards and shows six months per card, this month and the monthly average. Tap a card behind to bring it to the front, or a row to see its months and top categories. A Cards & accounts filter takes several choices.", "New Cards & accounts window: choose whose each card is or mark it shared, and add a RiseUp card's last 4 digits to join it with its statement.", "When a statement doesn't print the card number, you can say which card it is (optional). Recorded expenses can say which card or account paid (optional).", "Original card and bank marks for Israeli issuers; cards from anywhere else get a neutral look."], "he":  ["היום: עוזר חדש בראש מסך היום. אפשר לשאול את הבית שאלה, או להפוך הודעה לתוכנית אחת עם כמה פריטים ותזכורת לכל אחד, שנשמרים יחד כדי שתוכלו לחזור אליה.", "הוצאות: סינון לפי של מי הכרטיס. כל מבוגר מופיע עם הכרטיסים שלו מוערמים לצדו, וחשבונות הבנק מופיעים תחת \"משותף\". אפשר לבחור כמה בבת אחת, ואז לצמצם לכרטיס בודד. זה עובד אותו דבר עבור RiseUp ועבור דפי חשבון שיובאו. לפני כן, \"מקס\" לא מצא קניות שסונכרנו דרך RiseUp.", "סטטיסטיקה ← כסף: \"לפי אדם וכרטיס\" מציג את הכרטיסים של כל אחד מוערמים, עם שישה חודשים לכל כרטיס, החודש הנוכחי והממוצע החודשי. לחיצה על כרטיס מאחור מביאה אותו לחזית, ולחיצה על שורה מציגה את החודשים והקטגוריות המובילות שלו. מסנן \"כרטיסים וחשבונות\" מאפשר כמה בחירות.", "חלון חדש \"כרטיסים וחשבונות\": לבחור של מי כל כרטיס או לסמן אותו כמשותף, ולהוסיף 4 ספרות אחרונות לכרטיס מ־RiseUp כדי לחבר אותו לדף החשבון שלו.", "כשדף חשבון לא מציין את מספר הכרטיס, אפשר לציין איזה כרטיס זה (לא חובה). בהוצאה שנרשמה ידנית אפשר לציין באיזה כרטיס או חשבון שולם (לא חובה).", "סימנים מקוריים לחברות האשראי והבנקים בישראל; כרטיסים מכל מקום אחר מקבלים מראה ניטרלי."]},
 {"version":  "1.47.0", "date":  "2026-11-09", "en":  ["Choose what your family uses. Settings › Features lets a parent turn features on or off for the whole family, and each person can hide what they don't need, just for themselves. Nothing is deleted: turn a feature back on and everything returns. New families start with a short setup: a few questions, suggested features, and simple guides for connecting your own accounts."], "he":  ["בוחרים במה המשפחה משתמשת. בהגדרות › תכונות הורה מפעיל או מכבה תכונות לכל המשפחה, וכל אחד יכול להסתיר אצלו מה שלא צריך לו. שום דבר לא נמחק: מפעילים שוב והכול חוזר. משפחה חדשה מתחילה בהגדרה קצרה: כמה שאלות, תכונות מוצעות ומדריכים פשוטים לחיבור החשבונות שלכם."]},
 {"version":  "1.46.0", "date":  "2026-11-09", "en":  ["Puzzle: the \"more pieces\" sign is now a small arrow on the edge of the tray that gently nudges, so it no longer covers pieces. The tray always shows whole pieces, and swiping or tapping the arrow moves a full column at a time."], "he":  ["פאזל: השלט \"עוד חלקים\" הוא עכשיו חץ קטן בקצה המגש שזז בעדינות, כך שהוא כבר לא מסתיר חלקים. המגש תמיד מציג חלקים שלמים, והחלקה או לחיצה על החץ מזיזות עמודה שלמה בכל פעם."]},
 {"version":  "1.45.0", "date":  "2026-11-09", "en":  ["Expenses: the new \"Who we pay\" view shows at a glance which providers and subscriptions the family pays and how much — phone → Cellcom, TV → FreeTV, electricity, arnona, insurance, streaming and more. Messy statement names are grouped into one provider, price rises and overlapping services stand out, and you can rename, combine, hide or add a provider. With your household's AI connected, a short summary refreshes once a month. It replaces the Fixed bills list.","The yellow \"partial month\" note now sits below the numbers instead of between the controls and your data."], "he":  ["הוצאות: התצוגה החדשה \"למי משלמים\" מראה במבט אחד לאילו ספקים ומנויים המשפחה משלמת וכמה — סלולר ← סלקום, טלוויזיה ← FreeTV, חשמל, ארנונה, ביטוחים, סטרימינג ועוד. שמות מבולגנים מדפי החשבון מאוחדים לספק אחד, עליות מחיר ושירותים כפולים בולטים, ואפשר לשנות שם, לאחד, להסתיר או להוסיף ספק. כשה־AI של הבית מחובר, סיכום קצר מתעדכן פעם בחודש. התצוגה מחליפה את רשימת החיובים הקבועים.","ההערה הצהובה על \"חודש חלקי\" מופיעה עכשיו מתחת למספרים, ולא בין הכפתורים לנתונים."]},
 {"version":  "1.44.0", "date":  "2026-11-09", "en":  ["Puzzle: placed pieces leave the tray and the rest slide into the free spots, so the tray shrinks to one page. The tray scrolls smoothly, and a yellow \"+N\" sign shows how many more pieces are waiting; tap it to see them."], "he":  ["פאזל: חלקים שהונחו יוצאים מהמגש והשאר מחליקים למקומות הפנויים, כך שהמגש מצטמצם לעמוד אחד. הגלילה חלקה, ושלט צהוב \"+N\" מראה כמה חלקים עוד מחכים; לחיצה עליו מציגה אותם."]},
 {"version":  "1.43.0", "date":  "2026-11-09", "en":  ["Settings › Accounts & connections now shows parents how much AI Bayit uses, by person and feature, with this month's spend, a 30-day chart, and an estimate of how long your prepaid credit will last. Enter your credit once; the provider's billing page stays the real balance."], "he":  ["בהגדרות › חשבונות וחיבורים ההורים רואים עכשיו כמה AI ‏Bayit משתמש, לפי אדם ולפי שימוש, כולל ההוצאה החודש, גרף של 30 יום והערכה לכמה זמן תספיק היתרה ששילמתם מראש. מזינים את היתרה פעם אחת; היתרה האמיתית מופיעה בדף החיוב של הספק."]},
 {"version":  "1.42.0", "date":  "2026-11-09", "en":  ["Vouchers, Message to plan, Today suggestions and the Google Calendar connection are back. A release earlier today accidentally left them out; nothing you saved was lost.", "Includes offline mode, the new section menus and the Settings photo and Quiet hours fixes."], "he":  ["השוברים, \"הודעה לתוכנית\", ההצעות במסך היום והחיבור ל-Google Calendar חזרו. גרסה מוקדם יותר היום השמיטה אותם בטעות; שום דבר ששמרתם לא אבד.", "כולל את מצב האופליין, תפריטי האזורים החדשים ואת תיקוני התמונה ושעות השקט בהגדרות."]},
 {"version":"1.41.0","date":"2026-11-09","en":["Connect Google Calendar in Settings to share availability, import selected events, or keep a selected Bayit event updated in its own Google calendar."],"he":["בהגדרות אפשר לחבר את Google Calendar, לשתף זמינות, לייבא אירועים שבחרתם או לעדכן אירוע נבחר של בַּיִת ביומן נפרד בגוגל."]},
 {"version":"1.40.0","date":"2026-11-09","en":["Household › Vouchers keeps your vouchers private. Add a voucher photo, show its code at checkout, track the remaining balance, and set expiry reminders.","Today › Message to plan turns a message, photo or PDF into a draft to review before saving tasks or events.","Enable suggestions on Today to see overdue tasks, unassigned pickups and expiring vouchers."],"he":["ניהול הבית › שוברים מרכז את השוברים הפרטיים שלך. אפשר לצלם שובר, להציג קוד בקופה, לעדכן יתרה ולהגדיר תזכורת לפני פקיעה.","במסך היום, ״מהודעה לתוכנית״ הופך הודעה, תמונה או PDF לטיוטה שאפשר לבדוק לפני שמירת משימות או אירועים.","אפשר להפעיל הצעות במסך היום ולראות משימות באיחור, איסופים ללא אחראי ושוברים שמתקרבים לפקיעה."]},
 {"version": "1.39.1", "date": "2026-11-09", "en": ["The family photo is larger on phones, with the camera badge centered on the bottom edge.", "Quiet hours fields stay level, with the times centered vertically even when a label wraps."], "he": ["תמונת המשפחה גדולה יותר בטלפון וסמל המצלמה ממורכז בתחתית העיגול.", "שני שדות שעות השקט מיושרים זה מול זה והשעות ממורכזות בגובה, גם כשכותרת נפרסת לשתי שורות."]},
 {"version":  "1.39.0", "date":  "2026-11-09", "en":  ["Bayit now opens without a connection. You see your latest Today, Calendar, Tasks, Shopping and kids' day, marked \"Offline · showing data from …\". Ticks, new items and finished tasks made offline wait on your device and sync when you're back online.", "Section menus on every page now look the same: the icon above its label, with a half tile peeking out when there is more to scroll."], "he":  ["Bayit נפתח עכשיו גם בלי חיבור: רואים את היום, היומן, המשימות, הקניות והיום של הילדים כפי שנשמרו לאחרונה, עם הסימון \"אין חיבור · מוצג מידע מ-…\". סימונים, פריטים חדשים ומשימות שהושלמו בלי חיבור נשמרים במכשיר ומסתנכרנים כשהחיבור חוזר.", "תפריטי האזורים בכל העמודים נראים עכשיו אותו דבר: הסמל מעל השם, וחצי אריח מציץ בקצה כשיש עוד לגלול."]},
 {"version":  "1.38.1", "date":  "2026-11-09", "en":  ["Titles written in the other language (a Hebrew reminder in the English app, or the reverse) now line up with everything else in Notifications and other lists, instead of sitting on the far side."], "he":  ["כותרות שנכתבו בשפה האחרת (תזכורת בעברית באפליקציה באנגלית, או להפך) מיושרות עכשיו כמו כל השאר בהתראות וברשימות אחרות, במקום לשבת בצד הנגדי."]},
 {"version":  "1.38.0", "date":  "2026-11-09", "en":  ["Assigning someone now always lets them see it. If you choose \"Only me\" and assign another person, it becomes \"Selected people: you and them\", and the form says so.", "Today, My Space, reminders, Telegram and Push use the same rule for \"mine\":  what's assigned to you plus your own private items. The Tasks page shows everything you may see; use the person filter for \"assigned to me\"."], "he":  ["מי שמשויך למשימה, לאירוע או להערה תמיד רואה אותם. אם בוחרים ״רק אני״ ומשייכים מישהו נוסף, השיתוף הופך ל״אנשים נבחרים: אתם והמשויכים״, והטופס מציין זאת.", "״היום״, ״המקום שלי״, התזכורות, טלגרם וההתראות משתמשים באותו כלל ל״שלי״: מה שמשויך אליכם ומה שפרטי שלכם. דף המשימות מציג את כל מה שמותר לכם לראות; לסינון ״משויך אליי״ בחרו את עצמכם במסנן האנשים."]},
 {"version": "1.37.2", "date": "2026-11-09", "en": ["Statistics by area: Overview, Tasks, Calendar, Kids, Shopping and Money tabs with clear charts, summary cards and trends. Only the areas your family uses appear, children never see money, and missing data is shown as missing, not as zero.", "Household shows your data first: Expenses and Insurance have one short row of controls, compact view switches, and refresh/import/RiseUp in a Data & sync section at the bottom. Sections now run Expenses, Insurance, Documents, Maintenance, Pantry, Meals.", "Shopping: the icon picker opens on top of the item editor."], "he": ["סטטיסטיקה לפי תחום: לשוניות סקירה, משימות, יומן, ילדים, קניות וכסף עם גרפים ברורים, כרטיסי סיכום ומגמות. מופיעים רק התחומים שהמשפחה משתמשת בהם, ילדים לא רואים כסף, ונתונים חסרים מוצגים כחסרים ולא כאפס.", "ניהול הבית מציג קודם את הנתונים: בהוצאות ובביטוחים שורת פקדים אחת קצרה, מתגי תצוגה קומפקטיים, ורענון/ייבוא/RiseUp באזור 'נתונים וסנכרון' בתחתית. סדר האזורים: הוצאות, ביטוחים, מסמכים, תחזוקה, מזווה, ארוחות.", "קניות: בוחר הסמלים נפתח מעל חלון עריכת הפריט."]},
 {"version": "1.37.1", "date": "2026-11-08", "en": ["My Hero: larger touch areas, full-screen windows on phones, and the supermarket fits side by side on a phone held sideways. Products stand exactly on the shelves.", "A right pick gets a gold outline, a star burst and a pop; a wrong one a red outline and a shake (supermarket, budget shopping and puzzle)."], "he": ["הגיבור שלי: אזורי מגע גדולים יותר, חלונות במסך מלא בטלפון, והסופר מוצג זה לצד זה בטלפון לרוחב. המוצרים עומדים בדיוק על המדפים.", "בחירה נכונה מקבלת מסגרת זהב, פיצוץ כוכבים וקפיצה; בחירה שגויה מסגרת אדומה ורעידה (סופר, קנייה בתקציב ופאזל)."]},
 {"version": "1.37.0", "date": "2026-11-08", "en": ["My Hero: the garden responds again (planting, watering and harvesting by tap or drag); Rest is available whenever energy is below full; the puzzle no longer gets stuck and pieces can be dragged or tapped and then placed with a tap; supermarket products all sit on real shelves; Simon shows clearly after every round whether it was right or a mistake and moves on by itself.", "Statistics: one aligned filter row, full-width tabs and summary cards whose labels no longer overlap their numbers; children don't see the household money tab; Hebrew charts read right to left.", "My Space › My tasks shows your private tasks and everything assigned to you, including overdue and undated tasks today.", "Scrolling section bars keep their solid colour: only the tabs fade at the edge that has more, and the chosen tab always opens in full view."], "he": ["הגיבור שלי: הגינה מגיבה שוב (שתילה, השקיה וקטיף בלחיצה או בגרירה); אפשר ללכת לישון כל עוד האנרגיה לא מלאה; הפאזל כבר לא נתקע, ואפשר לגרור חלק או ללחוץ עליו ואז על המקום שלו; כל המוצרים בסופר עומדים על מדפים אמיתיים; סיימון מראה בבירור אחרי כל סיבוב אם צדקתם או טעיתם וממשיך לבד.", "סטטיסטיקה: שורת סינון אחת מיושרת, לשוניות ברוחב מלא וכרטיסי סיכום שהכותרות שלהם כבר לא עולות על המספרים; ילדים לא רואים את לשונית הכסף של הבית; גרפים בעברית נקראים מימין לשמאל.", "המקום שלי › המשימות שלי מציג את המשימות הפרטיות שלכם וכל מה שמשויך אליכם, כולל משימות באיחור ובלי תאריך היום.", "סרגלי אזורים נגללים שומרים על הצבע המלא שלהם: רק הלשוניות דוהות בצד שיש בו עוד, והלשונית שנבחרה תמיד נפתחת במלואה."]},
 {"version": "1.36.1", "date": "2026-11-08", "en": ["Journal: \"Assigned to\" in a note uses the same person chips as every other form.", "On phones, task and event details fill the screen; the Household filter window uses 44px fields with buttons that never wrap; times like 19:00 sit centred in their field."], "he": ["יומן הבית: \"משויך ל־\" בהערה משתמש באותם שבבי אנשים כמו בשאר הטפסים.", "בטלפון, פרטי משימה ואירוע ממלאים את המסך; חלון הסינון בניהול הבית בשדות של 44px עם כפתורים שלא נשברים לשתי שורות; שעות כמו 19:00 ממורכזות בשדה."]},
 {"version": "1.36.0", "date": "2026-11-08", "en": ["Journal and My Space: notes open in the same window as the rest of the app, with Details, When and Privacy sections, Cancel then Save, and Delete only on saved notes. On phones the editors and details fill the screen with the menu at the top or bottom.", "The journal has one search row with a Filters button, so the first entries show on the first screen. Rows are calmer, completed tasks show who did them, new notes stay in view after saving, and tags with spaces work."], "he": ["היומן והמקום שלי: הערות נפתחות באותו חלון כמו בשאר האפליקציה, עם הקטעים פרטים, מתי ופרטיות, ביטול ואז שמירה, ומחיקה רק בהערה שכבר נשמרה. בטלפון העריכה והפרטים ממלאים את המסך, כשהתפריט למעלה או למטה.", "ביומן יש שורת חיפוש אחת עם כפתור סינון, כך שהרישומים הראשונים נראים כבר במסך הראשון. השורות רגועות יותר, משימות שהושלמו מראות מי ביצע אותן, הערה חדשה נשארת בתצוגה אחרי השמירה, ותגיות עם רווחים עובדות."]},
 {"version": "1.35.1", "date": "2026-11-08", "en": ["Statistics, My Space and Journal buttons use the shared 44px size too."], "he": ["גם הכפתורים בסטטיסטיקה, במקום שלי וביומן הבית בגובה האחיד של 44px."]},
 {"version": "1.35.0", "date": "2026-11-08", "en": ["All pages now share one header: the title starts at the content edge with the same size and spacing, and Cards/List sits beside the title. The title underline is sharper.", "Buttons and fields share one 44px height across the app, including Settings, Household and Shopping, and Delete buttons are marked in red.", "Today's \"Little things to do\" shows every task assigned to you (today, overdue and without a date) and nothing assigned only to someone else; the kids' tasks stay in their own part below."], "he": ["כל העמודים מקבלים כותרת אחידה: הכותרת מתחילה בקצה התוכן באותו גודל ובאותם מרווחים, וכפתור כרטיסים/רשימה יושב ליד הכותרת. קו ההדגשה מתחת לכותרת חד יותר.", "כפתורים ושדות באותו גובה של 44px בכל האפליקציה, כולל הגדרות, ניהול הבית וקניות, וכפתורי מחיקה מסומנים באדום.", "\"משימות קטנות להיום\" מציגות את כל המשימות שמשויכות אליכם (להיום, באיחור ובלי תאריך) ולא משימות שמשויכות רק למישהו אחר; המשימות של הילדים נשארות בחלק משלהן למטה."]},
 {"version": "1.34.0", "date": "2026-11-08", "en": ["When someone else deletes, moves, renames or changes the place of an event, task or routine assigned to you, or removes you from it, Bayit tells you on Telegram, by Push and in the notifications inbox, and corrects reminders it already sent (\"Moved to Thu 12 Nov 16:40\", Snooze removed). Quick edits become one message, quiet hours delay it, and Settings → Notifications → \"Changes to things assigned to me\" turns it off.", "Today's \"Little things to do\" now also shows unfinished earlier tasks (Overdue) and tasks without a date (Anytime), like the Tasks page. Parents see the kids' tasks below their own, with each child's photo; Customize Today can hide them.", "Rows on Today show only the round photo of the assigned person at the end of the row, so titles get the full width.", "Routines on chosen days read \"5 days a week\" instead of \"Once\". The repeat \"Ends\" choice shows clearly which option is chosen and explains it.", "Your Bayit language is saved to your profile automatically, so Telegram uses the same language as the app. Calendar and form controls share one 44px height."], "he": ["כשמישהו אחר מוחק, מעביר, משנה שם או מקום של אירוע, משימה או שגרה שמשויכים אליכם, או מסיר אתכם מהם, Bayit מעדכן בטלגרם, בהתראה לטלפון ובתיבת ההתראות, ומתקן תזכורות שכבר נשלחו (\"הועבר ל־יום ה׳, 12 בנוב׳ ב־16:40\", בלי נודניק). עריכות רצופות הופכות להודעה אחת, בשעות השקט היא נשלחת אחר כך, ואפשר לכבות בהגדרות ← התראות ← \"שינויים בדברים שמשויכים אליי\".", "\"משימות קטנות להיום\" מציגות עכשיו גם משימות שלא הושלמו מימים קודמים (באיחור) ומשימות בלי תאריך, כמו בעמוד המשימות. הורים רואים את המשימות של הילדים מתחת לשלהם, עם התמונה של כל ילד; אפשר להסתיר בהתאמת מסך היום.", "בשורות של מסך היום מופיעה רק התמונה העגולה של מי שמשויך, בסוף השורה, כך שלכותרות יש את כל הרוחב.", "שגרות בימים נבחרים מוצגות כ\"5 ימים בשבוע\" ולא \"פעם אחת\". בחירת \"מסתיים\" מראה בבירור מה נבחר ומסבירה אותו.", "שפת Bayit נשמרת בפרופיל באופן אוטומטי, כך שטלגרם משתמש באותה שפה כמו האפליקציה. הפקדים בלוח השנה ובטפסים באותו גובה."]},
 {"version": "1.33.1", "date": "2026-11-08", "en": ["Telegram and phone reminders are checked again just before sending: a reminder goes out only if the item still happens on that day and within that time, so a moved or rescheduled event no longer sends a reminder for its old date.", "A snoozed reminder is no longer re-sent after its event moved, finished or already started, and reminders for a later day no longer offer \"Snooze 10 min\". Times that have passed say \"25 min ago\".", "Hebrew chats no longer show English error messages; button replies and Start-link replies follow your Bayit language. Insurance import shows Hebrew names. Money alerts keep merchant names whole and say \"Over by\" when a limit is exceeded."], "he": ["תזכורות בטלגרם ובטלפון נבדקות שוב רגע לפני השליחה: תזכורת נשלחת רק אם הפריט עדיין מתקיים באותו יום ובאותו זמן, כך שאירוע שהוזז כבר לא שולח תזכורת לתאריך הישן.", "תזכורת שנדחתה בנודניק לא נשלחת שוב אם האירוע הוזז, הסתיים או כבר התחיל, ותזכורות ליום אחר כבר לא מציעות \"נודניק 10 דק׳\". זמן שעבר מוצג כ\"לפני 25 דק׳\".", "צ׳אטים בעברית לא מקבלים יותר הודעות שגיאה באנגלית; תשובות לכפתורים ולקישור החיבור מוצגות בשפה שבחרתם ב־Bayit. ייבוא ביטוחים מציג שמות בעברית. התראות כסף שומרות על שם בית העסק המלא ומציינות \"חריגה של\" כשעוברים את המסגרת."]},
 {"version": "1.33.0", "date": "2026-11-08", "en": ["On phones every window (New list, filters, pantry, meals, expenses, insurance and more) opens full screen like the event and task forms: the title and close button on top, the content scrolls, and Cancel / Save stay at the bottom. This works with the menu at the top or at the bottom, and nothing from the page shows below the buttons.", "With the menu at the top, the phone event and task forms keep Save on the screen bottom without an empty strip below it.", "Hebrew page titles start at the page edge on every screen, like English, and the subtitle shows on landscape phones too.", "In Hebrew the three dots of More sit after the word, and scrolling tab bars fade only on the side that has more to show.", "Item pictures in Household forms line up with their name field, and window titles have one size; a tapped close button no longer shows a blue frame."], "he": ["בטלפון כל חלון (רשימה חדשה, סינון, מזווה, ארוחות, הוצאות, ביטוחים ועוד) נפתח במסך מלא כמו טופסי האירוע והמשימה: הכותרת וכפתור הסגירה למעלה, התוכן נגלל, וביטול / שמירה נשארים למטה. זה עובד עם התפריט למעלה או למטה, ושום דבר מהעמוד לא מופיע מתחת לכפתורים.", "כשהתפריט למעלה, בטופסי האירוע והמשימה בטלפון כפתור השמירה צמוד לתחתית המסך בלי רווח ריק מתחתיו.", "כותרות העמודים בעברית מתחילות בקצה העמוד בכל מסך, כמו באנגלית, וכותרת המשנה מופיעה גם בטלפון לרוחב.", "בעברית שלוש הנקודות של \"עוד\" מופיעות אחרי המילה, וסרגלי לשוניות נגללים דוהים רק בצד שיש בו עוד תוכן.", "תמונות הפריטים בטפסי ניהול הבית מיושרות לשדה השם, לכותרות החלונות גודל אחד, וכפתור סגירה שנלחץ כבר לא מציג מסגרת כחולה."]},
 {"version": "1.32.1", "date": "2026-11-08", "en": ["Household buttons keep comfortable inner spacing on every screen, and in landscape on phones the Documents toolbar stays on one row so the first document is visible."], "he": ["הכפתורים בניהול הבית שומרים על ריווח פנימי נוח בכל מסך, ובטלפון לרוחב סרגל המסמכים נשאר בשורה אחת כך שהמסמך הראשון נראה מיד."]},
 {"version": "1.32.0", "date": "2026-11-08", "en": ["Shopping fits more on screen: the first items now show on phones, including iPhone landscape, and the item, list and trip windows use the same section design as other forms.", "Adding an item that is already on the list keeps its unit (\"2 bottles\" + 1 = \"3 bottles\"), and the cursor stays ready for the next item.", "On Today, the Shopping label on a shopping task opens the shopping list, and lists can be renamed directly on wide screens.", "Household (meals, pantry, expenses, insurance, maintenance and documents) uses the shared page layout: a compact title, one row of section tabs that scrolls on phones, one step of spacing, and the first items visible on every screen, including iPhone landscape.", "Household forms and filters open in the shared window with sections, and dates are written the same way everywhere."], "he": ["הקניות נכנסות יותר טוב למסך: הפריטים הראשונים מופיעים כבר בטלפון, גם לרוחב, וחלונות הפריט, הרשימה והקנייה בנויים כמו שאר הטפסים.", "הוספת פריט שכבר ברשימה שומרת על היחידה שלו (\"2 בקבוקים\" + 1 = \"3 בקבוקים\"), והסמן נשאר מוכן לפריט הבא.", "במסך היום, התווית \"קניות\" במשימת קנייה פותחת את רשימת הקניות, ובמסך רחב אפשר לשנות שם רשימה ישירות.", "ניהול הבית (ארוחות, מזווה, הוצאות, ביטוחים, תחזוקה ומסמכים) בנוי עכשיו כמו שאר העמודים: כותרת קומפקטית, שורה אחת של לשוניות שנגללת בטלפון, מרווח אחיד, והפריטים הראשונים נראים בכל מסך, גם בטלפון לרוחב.", "הטפסים והסינונים של ניהול הבית נפתחים בחלון המשותף עם אזורים, והתאריכים כתובים באותה צורה בכל מקום."]},
 {"version": "1.31.0", "date": "2026-11-08", "en": ["Settings is reorganised into clear sections on every page, with equal-height cards and compact choices. Notifications groups reminders, quiet hours, delivery, preview, money goals and insurance reminders.", "The family name is edited in one place (Family), and the change is saved only after the household server confirms it.", "The Settings menu stays on one row on every screen; on phones the first setting is visible right away and the chosen tile is never hidden under the edge fade."], "he": ["ההגדרות מסודרות עכשיו באזורים ברורים בכל עמוד, עם כרטיסים בגובה אחיד ובחירות קומפקטיות. ההתראות מקבצות תזכורות, שעות שקט, ערוצי משלוח, תצוגה מקדימה, יעדים כספיים ותזכורות ביטוח.", "את שם המשפחה עורכים במקום אחד (משפחה), והשינוי נשמר רק אחרי שהשרת של הבית מאשר אותו.", "תפריט ההגדרות נשאר בשורה אחת בכל מסך; בטלפון ההגדרה הראשונה נראית מיד, והאפשרות שנבחרה אף פעם לא מוסתרת מתחת לדהייה שבקצה."]},
 {"version":"1.30.0","date":"2026-11-08","en":["Event, task and routine forms are grouped into clear sections (Details, When & where, Notifications, Privacy & permissions) that can collapse. On desktop they use two columns with Save and Cancel in one footer.","Events and tasks can have up to five reminders, such as 3 days, 1 day and 10 minutes before. Each one arrives once in Bayit, as a push notification and on Telegram. Settings › Notifications offers several default reminders per category, and all-day items can remind you “1 day before at 09:00”.","Tasks shows more on the first screen: list cards in one row, and one filter row with a Filters window for people, priority, order and search. A child can tick the steps of their own task, and tasks from a deleted list appear under General.","Hebrew text is clearer: normal letter spacing and cleaner weights for small text."],"he":["טפסי אירוע, משימה ושגרה מחולקים לאזורים ברורים (פרטים, מתי ואיפה, התראות, פרטיות והרשאות) שאפשר לכווץ. במחשב הם מוצגים בשתי עמודות, עם שמירה וביטול בתחתית אחת.","לאירועים ולמשימות אפשר להגדיר עד חמש תזכורות, למשל 3 ימים, יום ו־10 דקות לפני. כל אחת מגיעה פעם אחת באפליקציה, בהתראת פוש ובטלגרם. בהגדרות › התראות אפשר לבחור כמה תזכורות ברירת מחדל לכל סוג, ולפריטים של יום שלם אפשר תזכורת „יום לפני ב־09:00”.","במשימות רואים יותר במסך הראשון: כרטיסי הרשימות בשורה אחת, ושורת סינון אחת עם חלון סינון לאנשים, עדיפות, סדר וחיפוש. ילד יכול לסמן את השלבים של המשימה שלו, ומשימות מרשימה שנמחקה מופיעות בכללי.","הטקסט בעברית ברור יותר: ריווח רגיל בין האותיות ומשקל נקי יותר לטקסט קטן."]},
 {"version":"1.29.2","date":"2026-11-08","en":["Phone event, task and routine forms keep Save and Cancel on a solid bar right above the menu, and Note shows an example of what to write.","Agenda is now a rolling list of what is coming up from today, while Week stays the Sunday–Saturday planner. People on event cards have the same white ring as elsewhere.","Today labels only real repeats, with their frequency. On phones every task lines up the same way, sections have a divider, and Customize has a centred sliders icon."],"he":["בטפסי אירוע, משימה ושגרה בטלפון כפתורי השמירה והביטול נמצאים בפס אטום ממש מעל התפריט, ובשדה ההערה מוצגת דוגמה למה לכתוב.","סדר היום הוא עכשיו רשימה מתגלגלת של מה שמתוכנן החל מהיום, ותצוגת השבוע נשארת מתכנן מראשון עד שבת. לאנשים בכרטיסי האירועים יש אותה מסגרת לבנה כמו בשאר האפליקציה.","מסך היום מסמן רק משימות שחוזרות באמת, עם התדירות. בטלפון כל המשימות מיושרות באותו אופן, יש קו מפריד בין האזורים ולכפתור ההתאמה סמל ממורכז."]},
 {"version":"1.29.1","date":"2026-11-08","en":["Calendar shows more of your week: a smaller title, New event beside it and one toolbar row. Phones show two to three days on the first screen, and landscape phones now show events.","Agenda titles wrap to two lines instead of being cut short. The desktop Month day list is wider, and event details use one title size.","Fixed: an event opened from a link no longer reappears when you switch to Month, Hebrew previous/next arrows point the right way, and Cards/List appears only in Week."],"he":["לוח השנה מציג יותר מהשבוע: כותרת קטנה יותר, אירוע חדש לידה ושורת כלים אחת. בטלפון רואים שניים־שלושה ימים במסך הראשון, ובטלפון לרוחב מוצגים עכשיו אירועים.","כותרות בסדר היום עוברות לשתי שורות במקום להיחתך. רשימת היום בתצוגת החודש במחשב רחבה יותר, ובפרטי האירוע יש גודל כותרת אחיד.","תוקן: אירוע שנפתח מקישור לא מופיע שוב במעבר לחודש, החיצים הקודם/הבא בעברית מצביעים לכיוון הנכון, וכרטיסים/רשימה מופיע רק בתצוגת שבוע."]},
 {"version":"1.29.0","date":"2026-11-08","en":["Telegram messages share one clear layout: an icon and bold title, the date or time, short sections and a hint. Reminders, the morning summary, alerts, commands, imports and AI replies all follow it.","Hebrew Telegram messages read right to left on every line, with commands kept intact. Dates, quantities and counts are written in your language instead of 2026-11-08 or “12 items”.","/tasks, /week, /lists and /shopping match the morning summary, and AI answers show tables, nested lists and links clearly."],"he":["הודעות הטלגרם בנויות באותו מבנה ברור: סמל וכותרת מודגשת, התאריך או השעה, אזורים קצרים והערה. כך נראות התזכורות, סיכום הבוקר, ההתראות, הפקודות, הייבוא ותשובות ה־AI.","הודעות טלגרם בעברית נקראות מימין לשמאל בכל שורה, והפקודות נשמרות שלמות. תאריכים, כמויות ומספרים כתובים בשפה שלכם במקום 2026-11-08 או „12 items”.","‎/tasks, ‎/week, ‎/lists ו־‎/shopping תואמים לסיכום הבוקר, ותשובות ה־AI מציגות טבלאות, רשימות מקוננות וקישורים בצורה ברורה."]},
 {"version":"1.28.2","date":"2026-11-08","en":["Today is more compact on desktop, tablet and phones: a smaller title, a one-row week strip, and sections that start higher. Text size settings now scale the Today title.","Today task rows keep the checkbox, icon, name and assigned person on one aligned line wherever there is room.","Customize Today opens one clear list to show, hide and reorder sections. A task completed by mistake can be unchecked right away."],"he":["מסך היום קומפקטי יותר במחשב, בטאבלט ובטלפון: כותרת קטנה יותר, שורת שבוע אחת ואזורים שמתחילים גבוה יותר. גודל הטקסט בהגדרות משנה גם את כותרת המסך.","שורות המשימות במסך היום מציגות את תיבת הסימון, הסמל, השם והאדם המשויך בשורה אחת מיושרת כשיש מקום.","התאמת מסך היום נפתחת כרשימה אחת ברורה להצגה, הסתרה וסידור האזורים. משימה שסומנה בטעות אפשר לבטל מיד."]},
 {"version":"1.28.1","date":"2026-11-08","en":["Today assignee labels are compact on desktop and phones, while the tablet section layout is preserved.","Multiple assigned or insured people use consistent overlapping avatars. Complete names remain available in details and accessible labels; individual people choices are preserved."],"he":["תגיות המשויכים במסך היום קומפקטיות במחשב ובטלפון, תוך שמירה על פריסת האזורים בטאבלט.","כמה משויכים או מבוטחים מוצגים כאווטארים חופפים בעקביות. כל השמות זמינים בפרטים ובתוויות הנגישות; בחירות האנשים נשארות נפרדות."]},
 {"version":"1.28.0","date":"2026-11-08","en":["Today gives tablet agenda and tasks room, uses Calendar people pills, and hides completed occurrences. Tasks opens on Today and To do with readable priority labels. Hebrew mirrors the header.","Month event details have two readable desktop columns and reachable actions. Phone and tablet sheets retain their return path.","Notifications support left-swipe removal, Remove all, clear empty filters and recovery after refused saves. The bell counter is compact and centered.","Each connection opens in a focused dialog with a top Close button. Maps puts its keys first and makes required Google confirmation clear.","The parent area fills the content width in both places and preserves the entered PIN when opening fails. Existing household codes are preserved.","Other assignees with access receive shared-task completion updates, respecting notification settings, quiet hours and duplicate protection."],"he":["מסך היום בטאבלט נותן מקום לסדר היום ולמשימות, משתמש בתגיות האנשים של היומן ומסתיר פעילויות שהושלמו. משימות נפתחות על היום ולביצוע עם תוויות עדיפות ברורות. ההדר משתקף בעברית.","פרטי אירוע בחודש מוצגים בשתי עמודות קריאות במחשב עם פעולות נגישות. בטלפון ובטאבלט נשמרת החזרה לרשימת היום.","בהתראות נוספו מחיקה בהחלקה שמאלה, מחיקת הכול, הסבר למסנן ריק והתאוששות משמירה שסורבה. מונה הפעמון קטן וממורכז.","כל חיבור נפתח בחלון ממוקד עם סגירה בראשו. במפות שדות המפתחות מופיעים קודם ואישור Google הנדרש מוצג בבירור.","אזור ההורים ממלא את רוחב התוכן בשתי הכניסות ושומר את הקוד שהוקלד אם הפתיחה נכשלת. קוד בית קיים אינו משתנה.","משויכים נוספים בעלי גישה מקבלים עדכון על השלמת משימה משותפת, תוך כיבוד העדפות ההתראות, שעות השקט ומניעת כפילויות."]},
 {"version":"1.27.0","date":"2026-11-08","en":["Kids has one stable header and compact navigation matching Household. Both children stay visible as direct shared portrait/name choices.","The selected child follows My day, Routines, My Hero and Parents. New activities select that child in advance; My Hero has a clear subtitle.","Page actions sit below navigation. Turns explains the shared order and shows the selected child's activity history with readable statuses.","Parent coin bonuses and their history appear only in Parents. Changing the child clears an unfinished bonus reason; selection waits during saving.","Garden decorations stay clear of signs even after opening Games first. Existing purchases, balances, progress and access rules are preserved."],"he":["באזור הילדים יש כותרת קבועה ותפריט קומפקטי כמו בניהול הבית. שתי הדמויות והשמות גלויים לבחירה ישירה.","הילד שנבחר מלווה את היום שלי, השגרות, הגיבור שלי ואזור ההורים. פעילות חדשה משויכת אליו מראש, ולגיבור שלי יש כותרת משנה ברורה.","פעולות המסך מופיעות מתחת לתפריט. מסך התורות מסביר את הסדר המשותף ומציג את היסטוריית הפעילויות של הילד שנבחר עם מצבים קריאים.","הענקות מטבעות וההיסטוריה שלהן מופיעות רק אצל ההורים. החלפת ילד מנקה סיבת הענקה שטרם נשלחה; הבחירה מושהית בזמן שמירה.","קישוטי הגינה נשארים רחוקים מהשלטים גם אחרי כניסה למשחקים. הרכישות, היתרות, ההתקדמות וההרשאות הקיימות נשמרות."]},
 {"version":"1.26.1","date":"2026-11-08","en":["Kids, My Hero, the garden and the parent card align to the full content width on larger screens. Child names are centered.","Picture puzzle shows all sixteen matching-size pieces together on desktop, with an aligned board and tray. Phones and tablets have a swipe tray without page buttons.","The magnifying glass stays complete when worn with a hat for all eight children, including portraits.","Inner tabs keep their menu and focus, without replaying the whole-page entrance or resetting scroll. Editor and main-section navigation retain their normal behavior."],"he":["מסכי הילדים, הגיבור שלי, הגינה וכרטיס ההורים מיושרים לרוחב התוכן במסכים גדולים. שמות הילדים ממורכזים.","במחשב כל שישה עשר חלקי הפאזל מוצגים יחד בגודל תואם ללוח, עם כותרות מיושרות. בטלפון ובטאבלט מחליקים במגש בלי כפתורי מעבר בין דפים.","זכוכית המגדלת נשארת שלמה גם עם כובע בכל שמונה הדמויות, כולל דיוקנאות.","מעבר בין לשוניות פנימיות שומר על התפריט והמיקוד, בלי להפעיל מחדש את אנימציית כל העמוד או לאפס גלילה. המעבר לטפסים ולמסכים ראשיים נשמר."]},
 {"version":"1.26.0","date":"2026-11-07","en":["Picture puzzle has 12 illustrated stages, full-color aligned pictures, clear contour hints and matching-size pieces across phone, tablet and desktop.","Every completed game automatically earns saved XP and shop coins, including repeat wins. Simon has five rounds and clean colored lights.","Supermarket search keeps the requested product visible. Garden counts align, signs and decorations stay separate and pixel shadows stay inside the garden.","Parent bonuses select a real child and show a clear recipient, saved confirmation and refreshed, aligned history with reasons and dates."],"he":["פאזל התמונות כולל 12 שלבים מאוירים, תמונה חדה ומיושרת, רמז במסגרת ברורה וחלקים בגודל שתואם ללוח בטלפון, בטאבלט ובמחשב.","כל משחק שהושלם מעניק אוטומטית XP ומטבעות שנשמרים בחשבון, גם בסיבובים חוזרים. בסיימון חמישה רצפים וכפתורי צבע ללא כיתוב.","המוצר המבוקש בסופר נשאר גלוי. ספירות כלי הגינה מיושרות, השלטים והקישוטים מופרדים והצללים נשארים בגבולות הגינה.","בחירת הילד ואישור ההענקה ברורים, והיסטוריית מטבעות הבונוס מתרעננת מיד עם יישור אחיד לסיבה, לתאריך ולסכום."]},
 {"version": "1.25.2", "date": "2026-11-07", "en": ["Phone Kids completion buttons fit their full label and check mark, including larger text and compact lists."], "he": ["כפתורי השלמת הפעילויות בילדים מותאמים לטקסט המלא ולסימן הווי בטלפון, גם בטקסט מוגדל וברשימות צפופות."]},
 {"version":"1.25.1","date":"2026-11-07","en":["Profile Save/Cancel appears only for unsaved changes and stays with the profile fields while scrolling. Refused saves retain the draft for retry."],"he":["פעולות השמירה בפרופיל מופיעות רק אחרי שינוי ונשארות בתוך הכרטיס בזמן גלילה. שמירה שסורבה משאירה טיוטה לניסיון חוזר."]},
 {version:'1.25.0',date:'2026-11-07',en:[
  'The selected blue-and-yellow Bayit logo appears throughout the app, loading and sign-in screens, notifications and installation icons. In-app light and night logos have real transparency.',
  'Tasks keep every assignee on one shared task, show the complete assignment in details, and send each recipient reminders according to their own access and preferences.',
  'The month calendar has clearer day cells, readable date markers and an accessible day sheet; Week and Agenda keep their existing layouts.',
  'My Hero adds a clearer food fridge, collection and room placement, child care poses, garden controls, interlocking puzzles and Simon. Rest restores energy over five minutes and wakes the child automatically.',
  'Authenticated parents can grant virtual bonus coins with a reason and history in a protected parent area. Coins and XP remain separate.'
 ],he:[
  'הלוגו הכחול־צהוב שנבחר מופיע ברחבי האפליקציה, בטעינה ובכניסה, בהתראות ובסמלי ההתקנה. לוגו היום והלילה בתוך האפליקציה שקופים באמת.',
  'משימות שומרות את כל המשויכים באותה משימה, מציגות את השיוך המלא בפרטים ושולחות לכל נמען תזכורות לפי ההרשאות וההעדפות שלו.',
  'תצוגת החודש ביומן מציגה תאים וסימוני תאריכים ברורים וחלון נגיש לאירועי היום; מבנה השבוע וסדר היום נשמר.',
  'הגיבור שלי כולל מקרר אוכל ברור, אוסף וסידור החדר, תנוחות טיפול, כלים בגינה, פאזלים משתלבים וסיימון. מנוחה ממלאת אנרגיה במשך חמש דקות ומעירה את הדמות אוטומטית.',
  'הורים מחוברים יכולים להעניק מטבעות משחק עם סיבה והיסטוריה באזור הורים מוגן. מטבעות ונקודות ניסיון נשארים נפרדים.'
 ]},
 {version:'1.24.2',date:'2026-11-07',en:['Keep equal space above and below navigation buttons in either menu position, with a subtle shadow separating navigation from content.','Hide phone scrollbars while keeping normal scrolling available throughout the app.'],he:['ריווח שווה מעל ומתחת לכפתורי הניווט בשני מיקומי התפריט, עם צל עדין שמפריד בין התפריט לתוכן.','הסתרת פסי הגלילה בטלפון תוך שמירה על גלילה רגילה בכל המסכים והחלונות.']},
 {version:'1.24.0',date:'2026-11-07',en:[
  'My Hero keeps the Kids submenu and opens one clear activity at a time: Care, Garden, Games or Dress up.',
  'Care adds gentle need meters, simple action buttons and a food-only fridge and food shop; outfits stay in Dress up.',
  'One illustrated garden combines vegetable beds and orchard, with real seed packets, drag-or-tap planting, direct Water and Harvest tools, and all eight children working at the selected spot.',
  'Games explain free play, offer separate saved rounds and clear wake-up recovery. Picture puzzles use sixteen real interlocking pieces and show saved progress.'
 ],he:[
  'הגיבור שלי שומר על תפריט הילדים ומציג פעילות ברורה אחת בכל פעם: טיפול, גינה, משחקים או לבוש.',
  'הטיפול כולל מדדי צרכים רגועים, כפתורי פעולה פשוטים ומקרר וחנות לאוכל בלבד; בגדים ואביזרים נשארים במתלבשים.',
  'גינה מאוירת אחת משלבת ערוגות ומטע, שקיות זרעים, שתילה בגרירה או בשתי לחיצות, כלים ישירים להשקיה ולקטיף וכל שמונה הדמויות שעובדות ליד הצמח שנבחר.',
  'המשחקים מסבירים שמשחקים בחינם, שומרים סיבוב נפרד לכל משחק ומציעים התעוררות ברורה. פאזלי התמונות כוללים שישה עשר חלקים משתלבים ומציגים התקדמות שמורה.'
 ]},
 {version:'1.23.2',date:'2026-11-07',en:[
  'Keep the saving indicator aligned inside the header, with one clear server-backed saving state.',
  'Navigation and More follow the selected theme and menu color; menu-position labels and checkmarks stay aligned.',
  'Tighter phone menu spacing respects rounded screen corners and counts safe areas once. Rotation dismisses navigation overlays and restores scrolling.'
 ],he:[
  'מחוון השמירה מיושר בתוך ההדר ומציג מצב שמירה ברור לפי אישור השרת.',
  'הניווט ותפריט עוד מתאימים לערכת הנושא ולצבע התפריט; הטקסט וסימוני הבחירה במיקום התפריט מיושרים.',
  'צומצמו רווחים עודפים בתפריט הטלפון, הכפתורים מותאמים לפינות מסך מעוגלות ומרווחי הבטיחות נספרים פעם אחת. סיבוב סוגר חלונות ניווט ומשחרר גלילה.'
 ]},
 {version:'1.23.1',date:'2026-11-07',en:['Keep the sample-data status clear of the new menu in both positions, including Hebrew tablet and landscape layouts.'],he:['הודעת המידע לדוגמה נשארת מחוץ לתפריט החדש בשני המיקומים, כולל עברית, טאבלט ותצוגת רוחב.']},
 {version:'1.23.0',date:'2026-11-07',en:[
  'A compact shared header and horizontal menu, with a yellow selected state. Choose the menu below the header or at the bottom in Colors & appearance.',
  'Consistent Bayit branding, family default image and sign-in screens, with a hand-sketched paper loading animation and reduced-motion support.',
  'A cleaner month calendar grid. Tap a day to see its events and add an event for that date; the surrounding Calendar controls and other module layouts are preserved.'
 ],he:[
  'הדר משותף וקומפקטי ותפריט אופקי עם סימון צהוב לבחירה. בוחרים בתפריט מתחת להדר או בתחתית דרך צבעים ומראה.',
  'מיתוג Bayit, תמונת משפחה כברירת מחדל ומסכי כניסה עקביים, עם אנימציית טעינה בסגנון סקיצה ונייר ותמיכה בהפחתת תנועה.',
  'רשת חודש נקייה יותר ביומן. לחיצה על יום מציגה את אירועיו ומאפשרת הוספה לתאריך הזה; פקדי היומן ומבנה שאר המסכים נשמרים.'
 ]},
 {version:'1.22.2',date:'2026-11-07',en:['Restored Telegram replies, voice-message processing and scheduled morning summaries on Cloudflare. Provider requests keep redirect protection.'],he:['תוקנה התקשורת לטלגרם ב־Cloudflare: תשובות הבוט, טיפול בהודעות קוליות וסיכומי הבוקר. ההגנה מפני הפניית בקשות לספק אחר נשמרת.']},
 {version:'1.22.1',date:'2026-11-07',en:['Family members permitted to record home maintenance can complete a service even when a linked receipt or contact is private to its owner. The private link stays private and is preserved.'],he:['בני משפחה שמורשים לתעד תחזוקה יכולים לשמור טיפול גם כשהקבלה או איש הקשר המקושרים פרטיים לבעלים. הקישור הפרטי נשמר ונשאר פרטי.']},
 {version:'1.22.0',date:'2026-11-07',en:[
  'Combine multiple insurance types and people in dropdown filters, with statistics for the combined selection.',
  'Documents open inside Bayit, including PDF, photos, text and a read-only Excel view. Dates are optional. Filter by several categories or people, file type, privacy and dates, and sort the results.',
  'Summarize a document with your connected AI provider: review the draft, quoted facts and explicit dates, then choose what to add and save. Manual notes and original files are preserved.',
  'Contact and Household forms keep themed Save and Cancel actions reachable on phones. Maintenance adds editable starter tasks, filtering, service history and reminders; Pantry adds useful sorting and stock/date filters.',
  'Keep reusable recipes separately from dated meal plans, with preparation notes, ingredients and explicit sharing.',
  'Pin documents and other records to your personal Today screen. Optional Household widgets include documents, low pantry stock, home care, meals and insurance dates for adults. Pins follow the original access rules.'
 ],he:[
  'שלבו כמה סוגי ביטוח ואנשים במסנני בחירה מרובה, עם סטטיסטיקה לכל הבחירה יחד.',
  'מסמכים נפתחים בתוך Bayit, כולל PDF, תמונות, טקסט ותצוגת Excel לקריאה. תאריכים הם לבחירה. סננו לפי כמה קטגוריות או אנשים, סוג קובץ, פרטיות ותאריכים, ומיינו את התוצאות.',
  'סכמו מסמך בעזרת ספק ה־AI המחובר לבית: בדקו טיוטה, פרטים מצוטטים ותאריכים מפורשים, בחרו מה להוסיף ואז שמרו. הערות ידניות וקובצי המקור נשמרים.',
  'טופסי אנשי קשר וניהול הבית שומרים על פעולות שמירה וביטול נגישות בטלפון. תחזוקה כוללת דוגמאות לעריכה, סינון, היסטוריית טיפולים ותזכורות; המזווה כולל מיון ומסנני מלאי ותוקף.',
  'שמרו מתכונים לשימוש חוזר בנפרד מתוכנית ארוחות לתאריך, עם הוראות הכנה, מצרכים ושיתוף מפורש.',
  'נעצו מסמכים ורשומות נוספות במסך היום האישי. אזורים לבחירה כוללים מסמכים, מלאי נמוך, תחזוקה, ארוחות ותאריכי ביטוח למבוגרים. הנעיצות שומרות על הרשאות המקור.'
 ]},
 {
   version:'1.21.0',date:'2026-11-07',
   en:[
     'Choose who a document concerns separately from its uploader and viewers. Set private, family or selected-person access before uploading.',
     'Organize documents with multiple categories, personal categories and licensed icons; filter by person or category and manage labels without deleting files.',
     'Confirmed Har HaBituach imports through the website and linked Telegram bot retain the exact original report privately under Documents → Insurance, with source history and download/file management. Source reports remain separate from full policy terms.',
     'Insurance details preserve your original tab and filters, improve Hebrew/English and phone layouts, and make premiums, status, insured people and review checks clearer.',
     'Remember private ID-to-person matches for future report imports, with masked management and explicit insured-person choices. Matching never grants access or changes existing policies.'
   ],
   he:[
     'בוחרים למי המסמך קשור בנפרד ממי שהעלה אותו וממי שרשאי לצפות בו. מגדירים צפייה פרטית, משפחתית או לאנשים שנבחרו לפני ההעלאה.',
     'מסדרים מסמכים בכמה קטגוריות, יוצרים קטגוריות אישיות ובוחרים אייקונים מורשים; מסננים לפי אדם או קטגוריה ומנהלים תוויות בלי למחוק קבצים.',
     'ייבוא מאושר מהר הביטוח דרך האתר והבוט המקושר שומר את דוח המקור המדויק באופן פרטי במסמכים ← ביטוח, עם היסטוריית מקורות, הורדה וניהול הקובץ. דוח המקור נשאר נפרד מתנאי הפוליסה המלאים.',
     'פרטי הביטוח שומרים על הלשונית והסינון המקוריים, משפרים עברית/אנגלית ותצוגת טלפון, ומבהירים פרמיות, מצב, מבוטחים ובדיקות לבדיקה.',
     'אפשר לזכור באופן פרטי התאמת תעודה לאדם לייבואים הבאים, עם ניהול מוסתר חלקית ובחירת מבוטח מפורשת. ההתאמה אינה מעניקה גישה ואינה משנה פוליסות קיימות.'
   ]
 },
 {
   "version": "1.20.0",
   "date": "2026-11-07",
   "en": [
     "Insurance adds Summary, Policies and Review: grouped coverage rows, breakdowns by type and insured people, renewal/document checks, and separate report premiums and loaded debits.",
     "An optional AI review uses only selected authorized summaries, masks known identifiers and leaves policies unchanged. Original documents and payment details are excluded.",
     "People filters share the family portrait and face-stack picker on phone, tablet and desktop. Insurance filters close predictably and group rows become smaller in List.",
     "My Hero refines care scenes, simplifies room actions and improves garden scale, labels and character feedback. Add a separate fruit orchard with seeds, seedlings and contextual planting, watering and harvesting.",
     "Saved text and menu sizes are respected through phone rotation; Escape closes a nested choice before its form.",
     "Calendar day windows close before starting a new event, keeping controls and scrolling available when you return."
   ],
   "he": [
     "בביטוחים נוספו סיכום, פוליסות ולבדיקה: קיבוץ שורות כיסוי, חלוקה לפי סוג ומבוטחים, בדיקות חידוש ומסמכים, והפרדה בין פרמיות בדוחות לחיובים שנקלטו.",
     "בדיקת AI לבחירה משתמשת רק בסיכומים המורשים שנבחרו, מסתירה מזהים ידועים ואינה משנה פוליסות. מסמכי המקור ופרטי התשלומים אינם נשלחים.",
     "מסנני האנשים משתמשים בתמונת המשפחה ובבורר התמונות המשותף בטלפון, בטאבלט ובמחשב. מסנני הביטוח נסגרים כצפוי וקבוצות הפוליסות מצטמצמות בתצוגת רשימה.",
     "ב־My Hero שופרו סצנות הטיפול, פעולות החדר, הגינה, התוויות ומשוב הדמות. נוסף מטע פירות נפרד עם זרעים, שתילים ופעולות שתילה, השקיה וקטיף ליד הצמח.",
     "גודל הטקסט והתפריט שנשמרו מכובד גם בסיבוב הטלפון; Escape סוגר קודם בחירה מקוננת ומשאיר את הטופס פתוח.",
     "חלונית היום ביומן נסגרת לפני יצירת אירוע חדש, כדי שהמסננים והגלילה יישארו זמינים בחזרה ליומן."
   ]
 },
 {"version":"1.19.5","date":"2026-11-06","en":["Refresh an existing RiseUp connection without a new Google sign-in. Automatic refresh checks eligible connections hourly and respects provider wait times.","Sensitive connection changes retain Google verification; successful verification returns to the connection for an explicit retry.","Clearer landscape family menu and accessible notification counts."],"he":["רענון חיבור RiseUp קיים ללא כניסה חוזרת ל־Google. הרענון האוטומטי בודק חיבורים מתאימים מדי שעה ומכבד זמני המתנה של הספק.","שינויים רגישים בחיבור ממשיכים לדרוש אימות Google; אחרי אימות מוצלח חוזרים לחיבור לניסיון מפורש נוסף.","תפריט משפחה ברור יותר לרוחב וספירת התראות נגישה."]},
 {"version":"1.19.4","date":"2026-11-06","en":["Keep Save and Cancel reachable at the bottom of task, event and routine forms on short landscape screens. Improve the contrast of routine details."],"he":["שמירה וביטול נשארים נגישים בתחתית טופסי משימה, אירוע ושגרה גם במסכים נמוכים לרוחב. שופרה הניגודיות של פרטי השגרה."]},
 {"version":"1.19.3","date":"2026-11-06","en":["Better profile portrait/name spacing and action rows on phone, tablet and desktop.","Household statistics include accessible imported and manual money records once, with clear missing-data, loading and error states.","Choose a task list or General in task forms. Touch forms wait for your tap before opening the keyboard."],"he":["מרווחים ברורים יותר בין תמונות ושמות בפרופיל ובשורות הפעולות בטלפון, בטאבלט ובמחשב.","סטטיסטיקת הבית כוללת רשומות כספים מיובאות וידניות מורשות ללא ספירה כפולה, ומציגה בבירור מידע חסר, טעינה ושגיאות.","בוחרים רשימת משימות או כללי בטופס המשימה. בטפסי מגע המקלדת נפתחת רק אחרי לחיצה שלכם."]},
 {"version":"1.19.2","date":"2026-11-06","en":["Clear selected views, circular family and people portraits, readable month controls and stable phone profile/shopping layouts.","Calendar month days open their event list; Week List keeps the week together. Improve child selection and preserve page scrolling after closing dialogs."],"he":["התצוגה שנבחרה מסומנת בבירור, תמונות המשפחה והאנשים עגולות, בורר החודש קריא ופריסת הפרופיל והקניות בטלפון יציבה.","לחיצה על יום בחודש פותחת את אירועיו, ותצוגת רשימת השבוע מציגה את השבוע ברצף. שופרו בחירת ילדים והגלילה אחרי סגירת חלוניות."]},
 {"version": "1.19.1", "date": "2026-11-06", "en": ["Page scrolling resumes after closing an insurance editor, import window or notification inbox. Long insurance lists remain scrollable on desktop, tablet and phone."], "he": ["הגלילה חוזרת לאחר סגירת עריכת ביטוח, חלון ייבוא או תיבת ההתראות. רשימות ביטוחים ארוכות נגללות במחשב, בטאבלט ובטלפון."]},
 {"version": "1.19.0", "date": "2026-11-06", "en": ["A dedicated Insurance register imports Har HaBituach Excel reports, keeps every coverage row and original policy-number digits, and separates insured people from payers.", "Review payment matches and attach policy documents with their own validity dates; keep previous document versions.", "Choose renewal and document reminders. Send an insurance Excel report to your linked Telegram bot, choose the insured person and confirm private import.", "Find a step-by-step Har HaBituach import guide in Insurance notification settings. Reports are snapshots; no automatic government connection is configured.", "My Hero adds shopping with exact round budgets, supermarket search, rhythm and 16-piece puzzles, using the selected open cart and wooden shelves.", "Grow 12 crops through four illustrated stages in a six-plot garden: water, harvest, sell, use the virtual fridge and decorate. Absence does not kill crops.", "All eight child heroes keep fitted equipment and improved care scenes with stationary furniture. Progress, purchases and rewards wait for household confirmation."], "he": ["מסך ביטוחים ייעודי מייבא דוחות Excel מהר הביטוח, שומר את שורות הכיסוי ואת ספרות מספרי הפוליסה, ומפריד בין המבוטח למשלם.", "בודקים התאמות לתשלומים ומצרפים מסמכי פוליסה עם תאריכי תוקף נפרדים; גרסאות קודמות נשמרות בהיסטוריה.", "בוחרים תזכורות לחידוש ולמסמכים. שולחים דוח Excel לבוט הטלגרם המקושר, בוחרים מי המבוטח ומאשרים ייבוא פרטי.", "מדריך לייבוא מהר הביטוח מופיע בהגדרות התראות הביטוח. דוחות הם תמונת מצב; לא מוגדר חיבור ממשלתי אוטומטי.", "ב־My Hero נוספו קניות בתקציב מדויק לכל סיבוב, חיפוש בסופר, קצב ופאזלים של 16 חלקים, עם העגלה הפתוחה ומדפי העץ שנבחרו.", "מגדלים 12 גידולים בארבעה שלבים מאוירים בגינה עם שש ערוגות: משקים, קוטפים, מוכרים, משתמשים במקרר הווירטואלי ומקשטים. היעדרות אינה הורגת גידולים.", "כל שמונה דמויות הילדים שומרות על הציוד המותאם ומקבלות סצנות טיפול משופרות עם ריהוט קבוע. התקדמות, רכישות ופרסים ממתינים לאישור שרת הבית."]},
 {"version":"1.18.0","date":"2026-11-06","en":["Security: safer documents, verified child identity, privacy checks, device sessions and private installation controls.","Tap a money row for its complete original name, transaction and charge dates, source/payment details and six months of matching merchant history. Merchant names retain their beginning in Hebrew and English.","Record income, expenses and savings transfers separately. Configure monthly and category spending caps, advance warnings and separate goals for projected month-end money remaining and transfers actually recorded.","Choose finance alerts in Bayit, on your connected devices or in your linked Telegram chat, plus an optional weekly summary. Private and shared views use their own accessible records.","Expenses open on the current month, with compact filters, source sync times and a clear refresh action. Statistics follow the selected dates and loaded history.","Forms keep their draft after a refused save and confirm only after the household server accepts. Clearer Undo, deletion and list controls, full numeric times and consistent people/view controls.","Add an optional place name to events and tasks. Connect your installation’s Google Maps for address search and a compact preview; links open the original authorized activity.","Document and access checks have been strengthened. Device notifications now stop when you sign out; enable Push again on devices connected before this update."],"he":["אבטחה: מסמכים בטוחים יותר, אימות זהות ילדים, בדיקות פרטיות, ניתוק מכשירים ובקרות להתקנה פרטית.","לחיצה על תנועה פותחת את השם המקורי המלא, תאריכי העסקה והחיוב, פרטי המקור והתשלום ושישה חודשי היסטוריה של בית העסק. שמות שומרים על ההתחלה בעברית ובאנגלית.","רושמים הכנסות, הוצאות והפקדות לחיסכון בנפרד. מגדירים תקרות חודשיות ולפי קטגוריה, אזהרה מראש ושני יעדים נפרדים: יתרה צפויה בסוף החודש והפקדות שתועדו בפועל.","בוחרים התראות כספיות ב־Bayit, במכשירים המחוברים שלכם או בצ׳אט הטלגרם המקושר, וגם סיכום שבועי לבחירה. התצוגה הפרטית והמשותפת משתמשות כל אחת ברשומות המורשות שלה.","ההוצאות נפתחות בחודש הנוכחי, עם מסננים שנפתחים לפי הצורך, זמני סנכרון ורענון ברור. הסטטיסטיקה מציגה את התאריכים וההיסטוריה שנבחרו.","טופס שנדחה שומר את הטיוטה, ושמירה מאושרת רק אחרי אישור שרת הבית. חודדו ביטול פעולות, מחיקה ורשימות, שעות מלאות ופקדי בחירת אנשים ותצוגה.","מוסיפים לאירועים ולמשימות שם מקום אופציונלי. חיבור Google Maps של ההתקנה מאפשר חיפוש כתובת ומפה קטנה; קישור שיתוף פותח את הפעילות המקורית בהתאם להרשאות.","עודכנו בדיקות המסמכים והגישה למידע. התראות המכשיר נפסקות כשמתנתקים מהחשבון; במכשירים שחוברו קודם צריך להפעיל מחדש Push אחרי העדכון."]},
 {"version":"1.17.0","date":"2026-11-06","en":["My Hero is now a small virtual home: feed, shower, tidy up, play and rest. All eight characters eat at a table, shower behind a curtain and sleep covered in bed.","Collect 60 virtual items and 10 moves, stock your fridge and decorate your room. Stars come from real quest XP; spending keeps your level. Purchases and care wait for household confirmation."],"he":["הדמות שלי הופך לבית וירטואלי קטן: מאכילים, מתקלחים, מסדרים, משחקים ונחים. כל שמונה הדמויות אוכלות ליד שולחן, מתקלחות מאחורי וילון וישנות מכוסות במיטה.","אוספים 60 פריטים וירטואליים ו־10 תנועות, ממלאים מקרר ומקשטים את החדר. כוכבים מגיעים מה־XP של המשימות; הקניות שומרות על הרמה. קניות וטיפול ממתינים לאישור שרת הבית."]},
 {version:'1.16.0',date:'2026-11-06',en:['Compact list mode: Settings › Colors & appearance › Lists, or Cards | List on each page. Thin one-line rows that fit about twice as many tasks, items, expenses and more, lined up like a table.','Hebrew and English mix correctly: titles you type keep their word order in either interface, the title underline sits under the real last word, and + / − signs stay before the number.','Task rows give the text more room: the person’s photo at the edge, a line of the note, and XP only in the task details.','New tasks start with a notebook icon and new events with a calendar, instead of a dinner plate.'],he:['מצב רשימה מצומצמת: הגדרות › צבעים ומראה › רשימות, או כרטיסים | רשימה בכל עמוד. שורות דקות שמכניסות בערך פי שניים משימות, פריטים, הוצאות ועוד, מיושרות כמו טבלה.','עברית ואנגלית מתערבבות נכון: כותרות שכותבים שומרות על סדר המילים בכל שפת ממשק, הקו שמתחת לכותרת יושב מתחת למילה האחרונה האמיתית, והסימנים + / − נשארים לפני המספר.','בשורות המשימות יש יותר מקום לטקסט: תמונת האדם בקצה, שורה מההערה, ו־XP רק בפרטי המשימה.','משימה חדשה מתחילה עם אייקון מחברת ואירוע חדש עם לוח שנה, במקום צלחת אוכל.']},
 {version:'1.15.0',date:'2026-11-06',en:['Notifications on your phone or computer, like any app: Settings → Notifications → Notifications on this device. On iPhone, add Bayit to the Home Screen first.','Task priority: None, Low, Medium or High, with a coloured frame on the task, a priority filter, a “By priority” view and Top priorities on Today. Change it right from the task details.','Settings are now defaults: each event or task can choose its own reminder, and new tasks start with your chosen “done” and overdue updates.','On tablets and laptops the side menu shows your 5 chosen places and More; titles in details are underlined neatly under the last word.'],he:['התראות בטלפון או במחשב, כמו בכל אפליקציה: הגדרות ← התראות ← התראות במכשיר הזה. באייפון מוסיפים קודם את Bayit למסך הבית.','עדיפות במשימות: ללא, נמוכה, בינונית או גבוהה, עם מסגרת צבעונית, סינון לפי עדיפות, תצוגה „לפי עדיפות” ו„הכי חשוב” במסך היום. אפשר לשנות ישר מפרטי המשימה.','ההגדרות הן עכשיו ברירת מחדל: כל אירוע או משימה יכולים לבחור תזכורת משלהם, ומשימות חדשות מתחילות עם העדכונים שבחרתם.','בטאבלט ובמחשב נייד תפריט הצד מציג את 5 המקומות שבחרתם ו״עוד״; הכותרות בפרטים מודגשות בקו נקי מתחת למילה האחרונה.']},
 {version:'1.14.1',date:'2026-11-06',en:['Telegram messages are tidy: a bold header, short sections and one bullet per item, for /today, the AI’s answers and lists.','Daily summary on Telegram: choose a time in Settings → Accounts & connections → Telegram and get your calendar, tasks (important first), anything overdue, shopping and approvals each morning. It arrives even during quiet hours.'],he:['ההודעות בטלגרם מסודרות: כותרת מודגשת, חלקים קצרים ונקודה לכל פריט, ב־/today, בתשובות ה־AI וברשימות.','סיכום יומי בטלגרם: בחרו שעה בהגדרות ← חשבונות וחיבורים ← טלגרם וקבלו כל בוקר יומן, משימות (חשובות קודם), מה שבאיחור, קניות ואישורים. נשלח גם בשעות השקט.']},
 {version:'1.14.0',date:'2026-11-05',en:['Repeating tasks and events can end on a date, and repeat monthly or yearly. Every task and event shows who created it and when.','Ask to hear when someone finishes your task, or to alert you and the assignee if it isn’t done in time. Telegram tells you too, with a Done button.','After saving, the new task or event opens right where it was added.','A new Shopping page: one place to add items, lists you can see and switch clearly, compact rows, and Hebrew and English item names recognised with the right picture and category.','Calendar cards with one tidy layout, clearer today highlight, and details in a centred pop-up on tablets.','Picking people works the same everywhere, and the selected person is clearly marked. Sharing looks the same in every editor.','Tablets: a slim menu with your 5 chosen places (Settings › Quick menu) and More for the rest.','Expenses: a cleaner toolbar with one Add button, amounts that always fit, and restaurants from RiseUp correctly shown as Eating out.'],he:['משימות ואירועים שחוזרים יכולים להסתיים בתאריך, ולחזור כל חודש או כל שנה. בכל משימה ואירוע רואים מי יצר ומתי.','אפשר לבקש עדכון כשמישהו מסיים משימה שלכם, או התראה לכם ולמי שהמשימה עליו אם היא לא בוצעה בזמן. גם טלגרם מודיע, עם כפתור בוצע.','אחרי שמירה, המשימה או האירוע החדשים נפתחים בדיוק איפה שנוספו.','מסך קניות חדש: מקום אחד להוספה, רשימות ברורות ומעבר נוח ביניהן, שורות קומפקטיות, וזיהוי שמות מוצרים בעברית ובאנגלית עם התמונה והקטגוריה הנכונות.','כרטיסי יומן בסידור אחיד, סימון ברור של היום, ובטאבלט פרטים בחלון במרכז.','בחירת אנשים זהה בכל מקום והבחירה בולטת. גם בחירת השיתוף נראית אותו דבר בכל עורך.','טאבלט: תפריט צר עם 5 המקומות שבחרתם (הגדרות › תפריט מהיר) ו״עוד״ לכל השאר.','הוצאות: סרגל כלים נקי עם כפתור הוספה אחד, סכומים שתמיד נכנסים, ומסעדות מ־RiseUp מסווגות נכון כאוכל בחוץ.']},
 {version:'1.13.1',date:'2026-11-05',en:['Shared expenses (RiseUp and imported statements set to “Both parents”) are now visible to every adult in the home, including a partner who joined after they were connected.'],he:['הוצאות משותפות (RiseUp ודפי חשבון שהוגדרו ל„שני ההורים”) גלויות עכשיו לכל המבוגרים בבית, כולל בן או בת זוג שהצטרפו אחרי החיבור.']},
 {version:'1.13.0',date:'2026-11-05',en:['Telegram is now a full home assistant: just write, speak or send a photo to add, complete, move, edit or delete tasks, events, shopping items and notes, add expenses, or ask what you spent. Every change waits for Apply and can be undone.','A full “/” menu in Telegram: /today, /tasks and /shopping with tap-to-complete, /week, /lists, /note and /expenses. It appears on its own; no need to reconnect.','Ask AI in the app can now complete, move, edit and delete existing items too, and knows task lists, subtasks and anytime tasks.'],he:['טלגרם הוא עכשיו עוזר בית מלא: פשוט כתבו, דברו או שלחו תמונה כדי להוסיף, לסמן, להעביר, לערוך או למחוק משימות, אירועים, פריטי קניות והערות, להוסיף הוצאות או לשאול כמה הוצאתם. כל שינוי ממתין להחלה ואפשר לבטל.','תפריט „/” מלא בטלגרם: ‎/today,‏ ‎/tasks ו־‎/shopping עם סימון בהקשה, ‎/week,‏ ‎/lists,‏ ‎/note ו־‎/expenses. הוא מופיע לבד, בלי להתחבר מחדש.','„שאלו את ה־AI” באפליקציה יכול עכשיו גם לסמן, להעביר, לערוך ולמחוק פריטים קיימים, ומכיר רשימות משימות, תתי־משימות ומשימות בכל זמן.']},
 {version:'1.12.0',date:'2026-11-05',en:['Calendar: one tidy filter row, a new Agenda list with Add on every day, a clearer Month view with dots on phones, and Edit and Delete together in event details.','Delete anything you created — tasks, events, notes, shopping items and lists, pantry, expenses, bills, meals, maintenance — with a button or by swiping a row, and Undo right after.','iPhone landscape: a compact top and bottom bar instead of the sidebar, and a tidy menu with equal buttons.'],he:['יומן: שורת סינון מסודרת אחת, רשימת סדר יום חדשה עם הוספה בכל יום, תצוגת חודש ברורה יותר עם נקודות בטלפון, ועריכה ומחיקה יחד בפרטי האירוע.','מחיקת כל מה שיצרתם — משימות, אירועים, הערות, פריטי ורשימות קניות, מזווה, הוצאות, חשבונות, ארוחות ותחזוקה — בכפתור או בהחלקה, עם ביטול מיד אחר כך.','אייפון לרוחב: סרגל עליון ותחתון קומפקטיים במקום התפריט הצדדי, ותפריט מסודר עם כפתורים שווים.']},
 {version:'1.11.0',date:'2026-11-05',en:['On phones, Tasks, Calendar and Kids use one People button instead of a long row of names: it shows everyone’s faces, or the person you chose, and opens a sheet to pick someone.'],he:['בטלפון, במשימות, ביומן ובילדים יש כפתור אנשים אחד במקום שורה ארוכה של שמות: הוא מציג את כולם, או את מי שבחרתם, ופותח חלון לבחירה.']},
 {version:'1.10.1',date:'2026-11-05',en:['On Today and in the Home journal, the faces of the people involved now sit on their own line under the title.'],he:['בהיום וביומן הבית, התמונות של המשתתפים מופיעות עכשיו בשורה משלהן מתחת לכותרת.']},
 {version:'1.10.0',date:'2026-11-05',en:['Cards with several people show overlapping faces with a +N, on Today, Calendar, Journal, Shopping and task lists.','No scrollbars on phones and on sideways strips: a soft fade shows there is more to swipe.','Task rows line up like a table, and the selected person chip gets a clean ring around the photo.'],he:['כרטיסים עם כמה אנשים מציגים תמונות חופפות עם ‎+N, בהיום, ביומן, ביומן הבית, בקניות וברשימות המשימות.','בלי פסי גלילה בטלפון ובפסים שנגללים הצידה: דהייה רכה מראה שיש עוד להחליק.','שורות המשימות מסודרות כמו טבלה, והאדם שנבחר מקבל טבעת נקייה סביב התמונה.']},
 {version:'1.9.0',date:'2026-11-05',en:['A new Tasks page: shared task lists (only me, family or selected people), filters for today, this week, upcoming, a day, a person or done, tasks grouped by day, subtasks, and tasks with no date.','Plan a shopping trip from any shopping list. It shows up in Tasks and Today with how much is in the bag, and completes when everything is bought.','A friendlier date picker everywhere, a richer Home journal with the latest entries first, a bigger family photo in the menu, a sun for Today, and a button to collapse the menu.','Kids: name chips like the calendar and a pixel-block XP bar.'],he:['דף משימות חדש: רשימות משימות משותפות (רק אני, המשפחה או אנשים נבחרים), סינון להיום, לשבוע, לבקרוב, ליום, לאדם או לבוצע, משימות לפי ימים, תת־משימות ומשימות בלי תאריך.','תכננו קנייה מכל רשימת קניות. היא מופיעה במשימות ובהיום עם כמה כבר בסל, ומסתיימת כשהכול נקנה.','בוחר תאריכים נוח יותר בכל מקום, יומן בית עשיר יותר עם הרישומים האחרונים קודם, תמונת משפחה גדולה בתפריט, שמש להיום וכפתור לכיווץ התפריט.','ילדים: כרטיסי שמות כמו ביומן ופס XP של קוביות פיקסל.']},
 {version:'1.8.0',date:'2026-11-05',en:['A new opening screen and sign-in in the Bayit sunrise style, a tablet menu that fits without scrolling with Menu size that really changes spacing, AI provider logos, and friendly pixel helpers on empty lists.'],he:['מסך פתיחה וכניסה חדשים בסגנון הזריחה של Bayit, תפריט בטאבלט שנכנס בלי גלילה עם גודל תפריט שבאמת משנה את הריווח, לוגו לכל ספק AI, ודמויות פיקסל חביבות ברשימות ריקות.']},
 {version:'1.7.0',date:'2026-11-05',en:['Take photo: on phones and tablets, use the camera to add a document, the family photo, a profile photo or an image.','Camera pictures are made smaller before upload, so they are quick to save and stay readable.','Run Bayit anywhere: besides Cloudflare, Bayit now also runs with Docker on a home computer, NAS, Raspberry Pi or any cloud server, using the same code (see the self-hosting guide).','All your connections in one place: Settings → Accounts & connections shows Google, storage, AI, Telegram and RiseUp with live status, and sets each one up.','Today’s task list now matches the Tasks screen: icon, owner, repeats and XP, and a tap opens the task.','Loading screens now show a soft skeleton of the page instead of “Loading…” text, and opening your home shows a centred message.'],he:['צילום: בטלפון ובטאבלט אפשר להשתמש במצלמה כדי להוסיף מסמך, תמונת משפחה, תמונת פרופיל או תמונה.','תמונות מהמצלמה מוקטנות לפני ההעלאה, כך שהן נשמרות מהר ונשארות קריאות.','Bayit בכל מקום: מלבד Cloudflare, אפשר עכשיו להריץ את Bayit גם עם Docker על מחשב ביתי, NAS, ‏Raspberry Pi או כל שרת ענן, עם אותו קוד (ראו מדריך האחסון העצמי).','כל החיבורים במקום אחד: הגדרות ← חשבונות וחיבורים מציג את Google, האחסון, ה־AI, טלגרם ו־RiseUp עם מצב עדכני, ומגדיר כל אחד מהם.','רשימת המשימות במסך היום זהה עכשיו למסך המשימות: אייקון, אחראי, חזרה ו־XP, והקשה פותחת את המשימה.','מסכי הטעינה מציגים עכשיו שלד רך של הדף במקום הטקסט „טוען…”, ופתיחת הבית מציגה הודעה במרכז המסך.']},
 {version:'1.6.0',date:'2026-11-05',en:['Optional RiseUp connection: if you use RiseUp, Bayit reads your bank and card transactions from it every day (read-only), with step-by-step setup in Household → Expenses. Only you or both parents see them, as you choose, and imported statements are not counted twice.','Money is now called Expenses, and shows your live bank balance when RiseUp is connected.','Clearer navigation everywhere: section tiles, view switches with counts, and small filter chips. Add by hand is now a button.','New pixel-art celebrations when you add or finish things, a ringing bell and a save badge, with Calm, Playful or Party in Settings → Animations & celebrations.'],he:['חיבור אופציונלי ל־RiseUp: אם אתם משתמשים ב־RiseUp, Bayit קורא ממנו כל יום את תנועות הבנק והאשראי (לקריאה בלבד), עם הגדרה שלב אחר שלב במשק בית ← הוצאות. רק אתם או שני ההורים רואים אותן, לפי בחירתכם, ודפי חשבון שיובאו לא נספרים פעמיים.','הכסף נקרא עכשיו הוצאות, ומציג את יתרת הבנק העדכנית כש־RiseUp מחובר.','ניווט ברור יותר בכל מקום: אריחי אזורים, מתגי תצוגה עם מספרים ומסנני צ׳יפ קטנים. רישום ידני הוא עכשיו כפתור.','חגיגות פיקסל חדשות כשמוסיפים או מסיימים דברים, פעמון מצלצל ותג שמירה, עם רגוע, שובב או מסיבה בהגדרות ← אנימציות וחגיגות.']},
 {version:'1.5.0',date:'2026-11-05',en:['Choose your AI: Claude, OpenAI (including Codex models), Google Gemini, xAI Grok, or any OpenAI-compatible service, in Settings → AI.','Eight grown-up pixel characters, including a grandma and grandpa. Parents can show a character, a photo or an icon.','The character picker has Grown-ups and Kids groups.'],he:['בחרו את ה־AI שלכם: Claude,‏ OpenAI (כולל מודלי Codex),‏ Google Gemini,‏ xAI Grok או כל שירות תואם OpenAI, בהגדרות ← AI.','שמונה דמויות פיקסל למבוגרים, כולל סבתא וסבא. הורים יכולים להציג דמות, תמונה או אייקון.','בבחירת הדמות יש קבוצות של מבוגרים וילדים.']},
 {version:'1.4.0',date:'2026-11-05',en:['Money is clearer: a monthly summary, tappable categories with every purchase inside, and fixed bills with due dates.','New Today widgets: Money this month and Coming up: bills, plus an Add widget tile.','Share Bayit with friends on WhatsApp, Telegram or email (Settings → Family).','Each Household tab now explains what it is for; Expenses is now called Money.'],he:['הכסף ברור יותר: סיכום חודשי, קטגוריות שאפשר להקיש עליהן ולראות כל קנייה, וחיובים קבועים עם תאריכים.','רכיבים חדשים במסך היום: הכסף החודש וחשבונות קרובים, ואריח להוספת רכיב.','שתפו את Bayit עם חברים בוואטסאפ, בטלגרם או באימייל (הגדרות ← משפחה).','כל לשונית בניהול הבית מסבירה למה היא משמשת; הוצאות נקראות עכשיו כסף.']},
 {version:'1.3.0',date:'2026-11-05',en:['Money: import Bank Leumi and Max statements (PDF) in the app or through Telegram. Every total is checked against the statement, card charges are not counted twice, and you see income, spending, savings, recurring bills, a next-month forecast and optional tips from Claude.','Eight pixel characters for children (and anyone who likes them), each with the cap and moon cape.','Add a profile with a character or a photo, and a birthday.','Birthdays appear in the family calendar every year, with the age shown in the profile.','The family photo card is aligned on phones.'],he:['כסף: ייבוא דפי חשבון של בנק לאומי ומקס (PDF) באפליקציה או דרך טלגרם. כל סכום נבדק מול הדף, חיובי כרטיס לא נספרים פעמיים, ורואים הכנסות, הוצאות, חיסכון, חיובים קבועים, תחזית לחודש הבא וטיפים אופציונליים מ־Claude.','שמונה דמויות פיקסל לילדים (ולכל מי שאוהב), כל אחת עם הכובע וגלימת הירח.','הוספת פרופיל עם דמות או תמונה, ויום הולדת.','ימי הולדת מופיעים בלוח השנה המשפחתי בכל שנה, והגיל מוצג בפרופיל.','כרטיס תמונת המשפחה מיושר בטלפון.']},
 {version:'1.2.0',date:'2026-11-05',en:['Eight full color themes that change the background, cards, menu and buttons, in day and night.','Clearer Colors & appearance settings: theme previews, light, tinted or deep menu, and button color swatches.','A new phone menu that fits on one screen, with large section tiles.','The family photo and name line up neatly in the menu.'],he:['שמונה ערכות צבע מלאות שמשנות את הרקע, הכרטיסים, התפריט והכפתורים, ביום ובלילה.','הגדרות צבעים ומראה ברורות יותר: תצוגה מקדימה לכל ערכה, תפריט בהיר, צבעוני או עמוק, ובחירת צבע לכפתורים.','תפריט חדש בטלפון שנכנס במסך אחד, עם אריחים גדולים לכל אזור.','תמונת המשפחה והשם מיושרים יפה בתפריט.']},
 {version:'1.1.1',date:'2026-11-05',en:['Refined family menu, separate family photo editing, profile alignment, text sizes and white logos on dark sidebars.','Explicit viewing and editing permissions, with private notes, calendar and tasks in My Space.','Expanded Pantry, Expenses, Bills and Maintenance workflows.','Child invitations can link existing profiles while retaining routines and progress.','AI source cards, optional browser dictation and improved phone and tablet layouts.'],he:['תפריט משפחה משופר, עריכת תמונת משפחה נפרדת, יישור פרופיל, גדלי טקסט ולוגו לבן בתפריטים כהים.','הרשאות צפייה ועריכה מפורשות, עם הערות, יומן ומשימות פרטיות במקום שלי.','הרחבת ניהול המזווה, ההוצאות, החשבונות ותחזוקת הבית.','הזמנות ילדים יכולות לקשר פרופילים קיימים תוך שמירת השגרות וההתקדמות.','מקורות בתשובות AI, הכתבה אופציונלית בדפדפן ושיפור התצוגה בטלפון ובטאבלט.']},
 {version:'1.1.0',date:'2026-11-05',en:['Telegram: connect your own family bot for reminders with Done and Snooze buttons, a morning summary, and Claude chat that understands text, photos and voice messages.','Saving is reliable on iPhone: photos are compressed, and one refused change can no longer block later ones.','You only see “saved” after the household server confirms it. Otherwise you see what went wrong.','Simpler phone forms: the icon picker sits next to the name, Save stays at the bottom, and fields no longer zoom or overlap.','Calendar events line up with their day on every screen size.','Version and update check in Settings.','Title rays stay with the last word when a title wraps, and mirror in Hebrew.','Calendar portraits have a ring and soft shadow so they stand out.'],he:['טלגרם: חברו בוט משפחתי משלכם לתזכורות עם כפתורי „בוצע” ו„נודניק”, סיכום בוקר, וצ׳אט עם Claude שמבין טקסט, תמונות והודעות קוליות.','שמירה אמינה באייפון: תמונות נדחסות, ושינוי אחד שנדחה כבר לא חוסם שינויים אחרים.','ההודעה „נשמר” מופיעה רק אחרי אישור השרת, אחרת מוצג מה השתבש.','טפסים פשוטים יותר בטלפון: בחירת אייקון ליד השם, כפתור שמירה קבוע בתחתית, ושדות שלא מתקרבים ולא חופפים.','אירועי היומן מיושרים ליום שלהם בכל גודל מסך.','גרסה ובדיקת עדכונים בהגדרות.','הקרניים בכותרת נשארות ליד המילה האחרונה גם כשהכותרת נשברת לשתי שורות, ומתהפכות בעברית.','לתמונות בני המשפחה ביומן יש מסגרת וצל עדין כדי שיבלטו.']},
 {version:'1.0.0',date:'2026-11-04',en:['First family release: Today, calendar, tasks, shopping lists, journal, kids, household, statistics and Claude.'],he:['גרסה משפחתית ראשונה: היום, יומן, משימות, רשימות קניות, יומן הבית, ילדים, משק בית, סטטיסטיקה ו-Claude.']}
];

async function fetchLatest(){const response=await fetch('/version.json?t='+Date.now(),{cache:'no-store'});if(!response.ok)throw Error('Version information is unavailable.');const info=await response.json();if(typeof info.buildId!=='string')throw Error('Version information is unavailable.');return info}

// Shared across components so the banner and the Settings panel agree.
let shared={status:'idle',latest:null,checkedAt:null,error:''};const listeners=new Set();
const publish=next=>{shared={...shared,...next};listeners.forEach(fn=>fn(shared))};
export async function checkForUpdate(){if(shared.status==='checking')return shared;publish({status:'checking',error:''});try{const latest=await fetchLatest();publish({status:latest.buildId!==BUILD_ID&&BUILD_ID!=='dev'?'available':'current',latest,checkedAt:new Date()})}catch(error){publish({status:'error',error:error.message,checkedAt:new Date()})}return shared}
export function useUpdateStatus(){const [state,setState]=useState(shared);useEffect(()=>{listeners.add(setState);return()=>listeners.delete(setState)},[]);return state}
export const applyUpdate=()=>{if(!window.dispatchEvent(new Event('bayit-before-update',{cancelable:true}))){publish({status:'blocked'});return}const url=new URL(location.href);url.searchParams.set('v',String(shared.latest?.buildId||Date.now()));location.replace(url.href)};

// Checks after load, every 30 minutes and when the app returns to the foreground.
export function useAutomaticUpdateCheck(){useEffect(()=>{if(BUILD_ID==='dev')return;const run=()=>{if(document.visibilityState==='visible')checkForUpdate()},first=setTimeout(run,15000),interval=setInterval(run,30*60*1000);document.addEventListener('visibilitychange',run);
 // Remove the cache-busting parameter added by applyUpdate once the new build is running.
 const url=new URL(location.href);if(url.searchParams.has('v')){url.searchParams.delete('v');history.replaceState(null,'',url.href)}
 return()=>{clearTimeout(first);clearInterval(interval);document.removeEventListener('visibilitychange',run)}},[])}

const formatTime=(value,lang)=>{if(!value)return '';const date=new Date(value);return Number.isNaN(date.getTime())?'':date.toLocaleString(lang==='he'?'he-IL':'en-GB',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})};

export function UpdateBanner({T}){const state=useUpdateStatus();if(state.status!=='available')return null;return <div className="update-banner" role="status"><Sparkle size={20}/><span>{T('A new version of Bayit is ready.','גרסה חדשה של Bayit מוכנה.')}</span><button onClick={applyUpdate}><ArrowClockwise size={18}/>{T('Update now','עדכון עכשיו')}</button></div>}

export function AboutSettings({app:a,ui:{Button,Badge}}){const state=useUpdateStatus(),notes=RELEASE_NOTES,[allNotes,setAllNotes]=useState(false),shown=allNotes?notes:notes.slice(0,3);
 const message=state.status==='blocked'?a.T('Save or download unsent changes before reloading.','שמרו או הורידו שינויים שטרם נשלחו לפני טעינה מחדש.'):state.status==='checking'?a.T('Checking for updates…','בודקים עדכונים…'):state.status==='available'?a.T('Version '+(state.latest?.version||'')+' is available on this household server.','גרסה '+(state.latest?.version||'')+' זמינה בשרת הבית.'):state.status==='current'?a.T('This tab matches the installed server version.','הלשונית מעודכנת לגרסה המותקנת בשרת הבית.'):state.status==='error'?a.T('Could not check right now. Try again when you are online.','לא ניתן לבדוק כרגע. נסו שוב כשיש חיבור.'):BUILD_ID==='dev'?a.T('Local development build. Updates are checked on the published app.','גרסת פיתוח מקומית. בדיקת עדכונים פועלת באפליקציה המפורסמת.'):a.T('Updates are checked automatically.','בדיקת עדכונים מתבצעת אוטומטית.');
 return <div className="settings-v2 about-settings"><div className="settings-grid"><FormSection T={a.T} icon={ArrowClockwise} tone="blue" className="settings-wide" title={a.T('Version & updates','גרסה ועדכונים')}><section className="about-version-card"><img src={a.theme==='dark'?BRAND_ASSETS.markDark:BRAND_ASSETS.markLight} alt="" width="72" height="72"/><div><span className="field-label">{a.T('Bayit version','גרסת Bayit')}</span><strong className="about-version-number" dir="ltr">{APP_VERSION}</strong><small dir="ltr">{a.T('Build','בנייה')} {BUILD_ID}{BUILD_TIME?' · '+formatTime(BUILD_TIME,a.lang):''}</small></div><Badge color={a.cloud?'green':'yellow'}>{a.cloud?a.T('Family account','חשבון משפחתי'):a.T('Sample data','מידע לדוגמה')}</Badge></section>
 <section className="about-update-card"><div className="about-update-status">{state.status==='available'?<Sparkle size={26}/>:state.status==='current'?<CheckCircle size={26}/>:<Info size={26}/>}<div><strong>{message}</strong>{state.checkedAt&&<small>{a.T('Last checked','נבדק לאחרונה')} {formatTime(state.checkedAt,a.lang)}</small>}</div></div><div className="heading-actions">{state.status==='available'?<Button icon={ArrowClockwise} onClick={applyUpdate}>{a.T('Update now','עדכון עכשיו')}</Button>:<Button secondary icon={ArrowClockwise} disabled={state.status==='checking'||BUILD_ID==='dev'} onClick={checkForUpdate}>{a.T('Check for updates','בדיקת עדכונים')}</Button>}</div><p className="about-update-note">{a.T('The household owner installs server updates. This button loads the build they have already deployed. Save or download unsent changes before reloading.','בעל ההתקנה מתקין עדכוני שרת. הכפתור טוען את הגרסה שכבר פורסמה בשרת הבית. שמרו או הורידו שינויים שטרם נשלחו לפני טעינה מחדש.')}</p></section>
 </FormSection><FormSection T={a.T} icon={Sparkle} tone="yellow" className="about-release-notes settings-wide" title={a.T('What’s new','מה חדש')}>{shown.map(note=><article key={note.version}><header><strong dir="ltr">{note.version}</strong><small>{new Date(note.date+'T12:00Z').toLocaleDateString(a.lang==='he'?'he-IL':'en-US',{day:'numeric',month:'long',year:'numeric'})}</small></header><ul>{(a.lang==='he'?note.he:note.en).map(line=><li key={line}>{line}</li>)}</ul></article>)}{notes.length>3&&<div className="settings-shortcuts"><Button secondary onClick={()=>setAllNotes(!allNotes)}>{allNotes?a.T('Show only the latest','הצגת האחרונים בלבד'):a.T('Show earlier versions ('+(notes.length-3)+')','הצגת גרסאות קודמות ('+(notes.length-3)+')')}</Button></div>}</FormSection></div></div>}
